anization":null,"emoji":null,"example_en":"Yo también soy estudiante.","example_es":"I’m a student too.","difficulty":1,"tags":["basics"]},{"id":"es-estudiante","language_code":"es","unit_id":"es-a1-u02","text":"estudiante","translation_es":"student","accepted_translations":[],"ipa":null,"romanization":null,"emoji":"🎓","example_en":"Soy estudiante.","example_es":"I’m a student.","difficulty":1,"tags":["people"]},{"id":"es-uno","language_code":"es","unit_id":"es-a1-u03","text":"uno","translation_es":"one","accepted_translations":[],"ipa":null,"romanization":null,"emoji":"1️⃣","example_en":"Thiago tiene un año.","example_es":"Thiago is one year old.","difficulty":1,"tags":["numbers"]},{"id":"es-dos","language_code":"es","unit_id":"es-a1-u03","text":"dos","translation_es":"two","accepted_translations":[],"ipa":null,"romanization":null,"emoji":"2️⃣","example_en":"Hablo dos idiomas.","example_es":"I speak two languages.","difficulty":1,"tags":["numbers"]},{"id":"es-tres","language_code":"es","unit_id":"es-a1-u03","text":"tres","translation_es":"three","accepted_translations":[],"ipa":null,"romanization":null,"emoji":null,"example_en":"Tomás tiene tres años.","example_es":"Tomás is three years old.","difficulty":1,"tags":["numbers"]},{"id":"es-cuatro","language_code":"es","unit_id":"es-a1-u03","text":"cuatro","translation_es":"four","accepted_translations":[],"ipa":null,"romanization":null,"emoji":null,"example_en":"Dos y dos son cuatro.","example_es":"Two and two are four.","difficulty":1,"tags":["numbers"]},{"id":"es-cinco","language_code":"es","unit_id":"es-a1-u03","text":"cinco","translation_es":"five","accepted_translations":[],"ipa":null,"romanization":null,"emoji":null,"example_en":"Valentina tiene cinco años.","example_es":"Valentina is five years old.","difficulty":1,"tags":["numbers"]},{"id":"es-seis","language_code":"es","unit_id":"es-a1-u03","text":"seis","translation_es":"six","accepted_translations":[],"ipa":null,"romanization":null,"emoji":null,"example_en":"Mateo tiene seis años.","example_es":"Mateo is six years old.","difficulty":1,"tags":["numbers"]},{"id":"es-siete","language_code":"es","unit_id":"es-a1-u03","text":"siete","translation_es":"seven","accepted_translations":[],"ipa":null,"romanization":null,"emoji":null,"example_en":"Sofía tiene siete años.","example_es":"Sofía is seven years old.","difficulty":1,"tags":["numbers"]},{"id":"es-ocho","language_code":"es","unit_id":"es-a1-u03","text":"ocho","translation_es":"eight","accepted_translations":[],"ipa":null,"romanization":null,"emoji":null,"example_en":"Diego tiene ocho años.","example_es":"Diego is eight years old.","difficulty":1,"tags":["numbers"]},{"id":"es-nueve","language_code":"es","unit_id":"es-a1-u03","text":"nueve","translation_es":"nine","accepted_translations":[],"ipa":null,"romanization":null,"emoji":null,"example_en":"Camila tiene nueve años.","example_es":"Camila is nine years old.","difficulty":1,"tags":["numbers"]},{"id":"es-diez","language_code":"es","unit_id":"es-a1-u03","text":"diez","translation_es":"ten","accepted_translations":[],"ipa":null,"romanization":null,"emoji":"🔟","example_en":"Ella tiene diez años.","example_es":"She is ten years old.","difficulty":1,"tags":["numbers"]},{"id":"es-once","language_code":"es","unit_id":"es-a1-u03","text":"once","translation_es":"eleven","accepted_translations":[],"ipa":null,"romanization":null,"emoji":null,"example_en":"Claire tiene once años.","example_es":"Claire is eleven years old.","difficulty":1,"tags":["numbers"]},{"id":"es-doce","language_code":"es","unit_id":"es-a1-u03","text":"doce","translation_es":"twelve","accepted_translations":[],"ipa":null,"romanization":null,"emoji":null,"example_en":"Un año tiene doce meses.","example_es":"A year has twelve months.","difficulty":1,"tags":["numbers"]},{"id":"es-veinte","language_code":"es","unit_id":"es-a1-u03","text":"veinte","translation_es":"twenty","accepted_translations":[],"ipa":null,"romanization":null,"emoji":null,"example_en":"Tengo vei