nslation_es":"the partner","accepted_translations":["the couple"],"ipa":null,"romanization":null,"emoji":"💑","example_en":"Mi pareja es de Medellín.","example_es":"My partner is from Medellín.","difficulty":1,"tags":["relationships"]},{"id":"es-juntos","language_code":"es","unit_id":"es-a2-u11","text":"juntos","translation_es":"together","accepted_translations":[],"ipa":null,"romanization":null,"emoji":null,"example_en":"Vamos juntos a la fiesta.","example_es":"We’re going to the party together.","difficulty":1,"tags":["relationships"]},{"id":"es-nunca","language_code":"es","unit_id":"es-a2-u11","text":"nunca","translation_es":"never","accepted_translations":[],"ipa":null,"romanization":null,"emoji":null,"example_en":"Nunca tomo café de noche.","example_es":"I never drink coffee at night.","difficulty":1,"tags":["negation"]},{"id":"es-ya-no","language_code":"es","unit_id":"es-a2-u11","text":"ya no","translation_es":"no longer","accepted_translations":["not anymore"],"ipa":null,"romanization":null,"emoji":null,"example_en":"Ya no vivo en Guadalajara.","example_es":"I no longer live in Guadalajara.","difficulty":1,"tags":["negation"]},{"id":"es-nada","language_code":"es","unit_id":"es-a2-u11","text":"nada","translation_es":"nothing","accepted_translations":["anything"],"ipa":null,"romanization":null,"emoji":null,"example_en":"No hay nada en la mesa.","example_es":"There’s nothing on the table.","difficulty":1,"tags":["negation"]},{"id":"es-nadie","language_code":"es","unit_id":"es-a2-u11","text":"nadie","translation_es":"nobody","accepted_translations":["no one"],"ipa":null,"romanization":null,"emoji":null,"example_en":"No vino nadie a la fiesta.","example_es":"Nobody came to the party.","difficulty":1,"tags":["negation"]},{"id":"es-algo","language_code":"es","unit_id":"es-a2-u11","text":"algo","translation_es":"something","accepted_translations":[],"ipa":null,"romanization":null,"emoji":null,"example_en":"¿Quieres tomar algo?","example_es":"Do you want something to drink?","difficulty":1,"tags":["pronouns"]},{"id":"es-casi-nunca","language_code":"es","unit_id":"es-a2-u11","text":"casi nunca","translation_es":"hardly ever","accepted_translations":["almost never"],"ipa":null,"romanization":null,"emoji":null,"example_en":"Casi nunca como carne.","example_es":"I hardly ever eat meat.","difficulty":1,"tags":["frequency"]},{"id":"es-he-estado","language_code":"es","unit_id":"es-a2-u11","text":"he estado","translation_es":"I have been","accepted_translations":["I've been"],"ipa":null,"romanization":null,"emoji":null,"example_en":"Nunca he estado en Cusco.","example_es":"I have never been to Cusco.","difficulty":1,"tags":["perfect"]},{"id":"es-alguna-vez","language_code":"es","unit_id":"es-a2-u11","text":"alguna vez","translation_es":"ever","accepted_translations":[],"ipa":null,"romanization":null,"emoji":null,"example_en":"¿Alguna vez fuiste a Cancún?","example_es":"Have you ever been to Cancún?","difficulty":1,"tags":["perfect"]},{"id":"es-ha-sido","language_code":"es","unit_id":"es-a2-u11","text":"ha sido","translation_es":"it has been","accepted_translations":["it's been"],"ipa":null,"romanization":null,"emoji":null,"example_en":"Ha sido un día largo.","example_es":"It’s been a long day.","difficulty":1,"tags":["perfect"]},{"id":"es-creo-que","language_code":"es","unit_id":"es-a2-u12","text":"creo que","translation_es":"I think that","accepted_translations":["I believe"],"ipa":null,"romanization":null,"emoji":null,"example_en":"Creo que va a llover.","example_es":"I think it’s going to rain.","difficulty":1,"tags":["opinions"]},{"id":"es-me-parece-que","language_code":"es","unit_id":"es-a2-u12","text":"me parece que","translation_es":"it seems to me that","accepted_translations":[],"ipa":null,"romanization":null,"emoji":null,"example_en":"Me parece que es muy caro.","example_es":"It seems to me that it’s very expensive.","difficulty":1,"tags":["opinions"]},{"id":"es-estoy-de-acuerdo","language_code":"es","unit_id":"es-a2-u12","text":"estoy de acuerdo","translation_es":"I agree","accepted_translations":[],"ipa":null,"romanization":null,"emoji":"🤝","example_en":"Estoy de acuerdo contigo.","example_es":"I agree with you.","difficulty":1,"tags":["opinions"]},{"id":"es-para-mi","language_code":"es","unit_id":"es-a2-u12","text":"para mí","translation_es":"in my opinion","accepted_translations":["for me"],"ipa":null,"romanization":null,"emoji":null,"example_en":"Para mí, el té es mejor que el café.","example_es":"In my opinion, tea is better than coffee.","difficulty":1,"tags":["opinions"]},{"id":"es-deberias","language_code":"es","unit_id":"es-a2-u12","text":"deberías","translation_es":"you should","accepted_translations":[],"ipa":null,"romanization":null,"emoji":null,"example_en":"Deberías llamar a tu mamá.","example_es":"You should call your mom.","difficulty":1,"tags":["advice"]},{"id":"es-podriamos","language_code":"es","unit_id":"es-a2-u12","text":"podríamos","translation_es":"we could","accepted_translations":[],"ipa":null,"romanization":null,"emoji":null,"example_en":"Podríamos ir al cine.","example_es":"We could go to the cinema.","difficulty":1,"tags":["advice"]},{"id":"es-si-llueve","language_code":"es","unit_id":"es-a2-u12","text":"si llueve","translation_es":"if it rains","accepted_translations":[],"ipa":null,"romanization":null,"emoji":"☔","example_en":"Si llueve, nos quedamos en casa.","example_es":"If it rains, we’ll stay at home.","difficulty":1,"tags":["conditions"]},{"id":"es-sin-embargo","language_code":"es","unit_id":"es-a2-u12","text":"sin embargo","translation_es":"however","accepted_translations":[],"ipa":null,"romanization":null,"emoji":null,"example_en":"Es caro. Sin embargo, me gusta.","example_es":"It’s expensive. However, I like it.","difficulty":1,"tags":["connectors"]},{"id":"es-por-eso","language_code":"es","unit_id":"es-a2-u12","text":"por eso","translation_es":"that's why","accepted_translations":["so"],"ipa":null,"romanization":null,"emoji":null,"example_en":"Estoy enfermo, por eso no voy a la facultad.","example_es":"I’m sick, that’s why I’m not going to college.","difficulty":1,"tags":["connectors"]},{"id":"es-el-problema","language_code":"es","unit_id":"es-a2-u12","text":"el problema","translation_es":"the problem","accepted_translations":[],"ipa":null,"romanization":null,"emoji":null,"example_en":"El problema es el dinero.","example_es":"The problem is money.","difficulty":1,"tags":["problems"]},{"id":"es-la-solucion","language_code":"es","unit_id":"es-a2-u12","text":"la solución","translation_es":"the solution","accepted_translations":[],"ipa":null,"romanization":null,"emoji":"💡","example_en":"¿Cuál es la solución?","example_es":"What is the solution?","difficulty":1,"tags":["problems"]},{"id":"es-devolver","language_code":"es","unit_id":"es-a2-u12","text":"devolver","translation_es":"to give back","accepted_translations":["to return (something)"],"ipa":null,"romanization":null,"emoji":null,"example_en":"Mañana te devuelvo el libro.","example_es":"I’ll give you back the book tomorrow.","difficulty":1,"tags":["verbs"]},{"id":"es-el-dinero","language_code":"es","unit_id":"es-a2-u12","text":"el dinero","translation_es":"money","accepted_translations":["the money"],"ipa":null,"romanization":null,"emoji":"💵","example_en":"No tengo dinero para el viaje.","example_es":"I don’t have money for the trip.","difficulty":1,"tags":["money"]},{"id":"es-dice-que","language_code":"es","unit_id":"es-a2-u12","text":"dice que","translation_es":"he says that","accepted_translations":["she says that"],"ipa":null,"romanization":null,"emoji":null,"example_en":"Ana dice que hace frío.","example_es":"Ana says that it’s cold.","difficulty":1,"tags":["reported"]},{"id":"es-me-dijo-que","language_code":"es","unit_id":"es-a2-u12","text":"me dijo que","translation_es":"he told me that","accepted_translations":["she told me that"],"ipa":null,"romanization":null,"emoji":null,"example_en":"Juan me dijo que está enfermo.","example_es":"Juan told me that he’s sick.","difficulty":1,"tags":["reported"]},{"id":"es-ojala","language_code":"es","unit_id":"es-a2-u12","text":"ojalá","translation_es":"hopefully","accepted_translations":["I hope so"],"ipa":null,"romanization":null,"emoji":null,"example_en":"¡Ojalá que no llueva!","example_es":"Hopefully it won’t rain!","difficulty":1,"tags":["subjunctive"]},{"id":"es-para","language_code":"es","unit_id":"es-a2-u12","text":"para","translation_es":"for (a purpose)","accepted_translations":["in order to"],"ipa":null,"romanization":null,"emoji":null,"example_en":"Estudio español para viajar.","example_es":"I study Spanish in order to travel.","difficulty":1,"tags":["prepositions"]},{"id":"es-por","language_code":"es","unit_id":"es-a2-u12","text":"por","translation_es":"because of","accepted_translations":["through","by"],"ipa":null,"romanization":null,"emoji":null,"example_en":"No fui a la playa por la lluvia.","example_es":"I didn’t go to the beach because of the rain.","difficulty":1,"tags":["prepositions"]}],"lessons":[{"id":"es-a1-u01-l01","unit_id":"es-a1-u01","position":1,"title_es":"Hola, buenos días, adiós","objective_es":"Say hello and goodbye depending on the time of day.","intro":{"explanation":"Hola works at any time of day. To be more polite, use the time of day: buenos días in the morning, buenas tardes in the afternoon and buenas noches in the evening, both when you arrive and when you leave. To say goodbye: adiós, or the friendly hasta luego (see you later), which people use all the time, even if they won’t see you again that day. With a stranger, add señor or señora. The h in hola and hasta is silent.","examples":[{"target":"Buenos días, señora.","base":"Good morning, madam."},{"target":"Adiós, Martín. ¡Hasta luego!","base":"Goodbye, Martín. See you later!"}]},"takeaways":["You greet with hola, buenos días, buenas tardes or buenas noches.","You say goodbye with adiós or hasta luego."]},{"id":"es-a1-u01-l02","unit_id":"es-a1-u01","position":2,"title_es":"Gracias, por favor","objective_es":"Say thank you, please, yes and no.","intro":{"explanation":"Gracias is thank you and the answer is de nada (you’re welcome). Por favor is please. Sí (with an accent) is yes; no is no. Every vowel is pronounced, short and clear: gra-cias, fa-vor.","examples":[{"target":"Gracias, señora. — De nada.","base":"Thank you, madam. — You’re welcome."},{"target":"No, gracias.","base":"No, thank you."}]},"takeaways":["You say thank you with gracias and answer de nada.","You ask politely with por favor."]},{"id":"es-a1-u01-rev1","unit_id":"es-a1-u01","position":3,"title_es":"Review 1","objective_es":"Consolidate “Hola, buenos días, adiós” and “Gracias, por favor”.","intro":null,"takeaways":[]},{"id":"es-a1-u01-l03","unit_id":"es-a1-u01","position":4,"title_es":"¿Cómo estás?","objective_es":"Ask how someone is with tú or usted, and answer.","intro":{"explanation":"With a friend (tú): ¿cómo estás? and, to ask back, ¿y tú? With someone you treat formally (usted), the verb loses its final s: ¿cómo está? and ¿y usted? A typical answer: bien or muy bien, gracias. Use tú with friends, family and people your age, and usted with strangers, older people and in shops. Spanish usually leaves out tú (¿cómo estás?, not ¿cómo estás tú?), but you say it in ¿y tú?, where it carries the meaning. Tú has an accent; tu without one means your.","examples":[{"target":"¿Cómo estás? — Bien, ¿y tú?","base":"How are you? — Fine, and you?"},{"target":"Muy bien, gracias. ¿Y usted?","base":"Very well, thank you. And you?"}]},"takeaways":["You ask a friend ¿cómo estás? and ¿y tú?","You use ¿cómo está? and ¿y usted? with señor and señora."]},{"id":"es-a1-u01-l04","unit_id":"es-a1-u01","position":5,"title_es":"Me llamo…","objective_es":"Say your name and ask someone else’s.","intro":{"explanation":"To say your name: me llamo + name (literally “I call myself”). To ask a friend: ¿cómo te llamas? — the same verb, now ending in -as for tú: yo me llamo, tú te llamas. When you meet someone, say mucho gusto. The ll of llamo sounds like the y in yes: YA-mo.","examples":[{"target":"Me llamo Sofía.","base":"My name is Sofía."},{"target":"¿Cómo te llamas? — Me llamo Martín.","base":"What’s your name? — My name is Martín."}]},"takeaways":["You introduce yourself with me llamo and ask ¿cómo te llamas?","You answer an introduction with mucho gusto."]},{"id":"es-a1-u01-rev2","unit_id":"es-a1-u01","position":6,"title_es":"Review 2","objective_es":"Consolidate “¿Cómo estás?” and “Me llamo…”.","intro":null,"takeaways":[]},{"id":"es-a1-u01-l05","unit_id":"es-a1-u01","position":7,"title_es":"Hola, ¿cómo estás?","objective_es":"Understand short greetings in a conversation and a message.","intro":{"explanation":"In much of Latin America, friends and family greet each other with one kiss on the cheek (between women, and between a man and a woman); men usually shake hands or hug. In Spain it is two kisses. A short chat between friends: ¡Hola! ¿Cómo estás? — Bien, ¿y tú? In a message, you can close with adiós or hasta luego.","examples":[{"target":"¡Hola, Tomás! ¿Cómo estás?","base":"Hi, Tomás! How are you?"},{"target":"¡Muchas gracias! Hasta luego.","base":"Thanks a lot! See you later."}]},"takeaways":["You understand a greeting, a thank-you and a goodbye in a message.","You choose tú or usted depending on the person."]},{"id":"es-a1-u01-listen","unit_id":"es-a1-u01","position":8,"title_es":"Listening practice","objective_es":"Recognize the words and phrases of the unit by ear.","intro":null,"takeaways":[]},{"id":"es-a1-u01-words","unit_id":"es-a1-u01","position":9,"title_es":"Words of the unit","objective_es":"Fix the vocabulary of the unit: recognize it and write it.","intro":null,"takeaways":[]},{"id":"es-a1-u01-final","unit_id":"es-a1-u01","position":10,"title_es":"Final review","objective_es":"Show everything from “Greetings and introductions”.","intro":null,"takeaways":[]},{"id":"es-a1-u02-l01","unit_id":"es-a1-u02","position":1,"title_es":"Yo soy, tú eres","objective_es":"Say who you are and who other people are with ser.","intro":{"explanation":"Ser means to be, and it is irregular: yo soy (I am), tú eres (you are, to a friend), él es (he is), ella es (she is) and usted es (you are, formal). Spanish usually drops the pronoun: soy estudiante, ¿eres estudiante? And there is no “a” before a role: soy estudiante = I am a student.","examples":[{"target":"Yo soy estudiante.","base":"I am a student."},{"target":"Ella es Lucía. Él es Diego.","base":"She is Lucía. He is Diego."}]},"takeaways":["You use yo soy, tú eres, él es, ella es and usted es.","You say soy estudiante without a word for “a”."]},{"id":"es-a1-u02-l02","unit_id":"es-a1-u02","position":2,"title_es":"Mexicano, mexicana","objective_es":"Say your nationality and other people’s, for a man or a woman.","intro":{"explanation":"Nationalities are written with a small letter and change for women: mexicano → mexicana, argentino → argentina, italiano → italiana, brasileño → brasileña. Inglés and francés lose their accent in the feminine: inglesa, francesa. The written accent marks the stressed syllable: in-GLÉS, fran-CÉS. Estadounidense (from the US) is the same for men and women. The c in francés sounds like an s.","examples":[{"target":"Martín es argentino. Lucía es mexicana.","base":"Martín is Argentine. Lucía is Mexican."},{"target":"Emma es inglesa.","base":"Emma is English."}]},"takeaways":["You change -o to -a for a woman: italiano, italiana.","You write inglesa and francesa without an accent."]},{"id":"es-a1-u02-rev1","unit_id":"es-a1-u02","position":3,"title_es":"Review 1","objective_es":"Consolidate “Yo soy, tú eres” and “Mexicano, mexicana”.","intro":null,"takeaways":[]},{"id":"es-a1-u02-l03","unit_id":"es-a1-u02","position":4,"title_es":"¿De dónde eres?","objective_es":"Ask where someone is from and say your country and city.","intro":{"explanation":"To ask a friend: ¿de dónde eres? With usted: ¿de dónde es usted? To answer: soy de + place. El país (the country) is masculine and la ciudad (the city) is feminine: the article tells you the gender. In país the stress falls on the í, and in ciudad the c sounds like an s.","examples":[{"target":"¿De dónde eres? — Soy de Bogotá.","base":"Where are you from? — I’m from Bogotá."},{"target":"¿De dónde es usted, señor?","base":"Where are you from, sir?"}]},"takeaways":["You ask ¿de dónde eres? and answer soy de…","You say el país and la ciudad."]},{"id":"es-a1-u02-l04","unit_id":"es-a1-u02","position":5,"title_es":"Vivo en…, hablo…","objective_es":"Say where you live and which languages you speak, and say no.","intro":{"explanation":"Vivo en + place: I live in. Hablo + language: I speak. Languages are not capitalized: inglés, español, italiano. To say no, put no before the verb: no hablo francés. También means also or too: yo también hablo inglés. Careful with the endings: vivo is I live, vive is he or she lives; hablo is I speak, habla is he or she speaks.","examples":[{"target":"Vivo en Bogotá. Hablo inglés y español.","base":"I live in Bogotá. I speak English and Spanish."},{"target":"No hablo francés.","base":"I don’t speak French."}]},"takeaways":["You say where you live with vivo en and your languages with hablo.","You make a sentence negative with no before the verb."]},{"id":"es-a1-u02-rev2","unit_id":"es-a1-u02","position":6,"title_es":"Review 2","objective_es":"Consolidate “¿De dónde eres?” and “Vivo en…, hablo…”.","intro":null,"takeaways":[]},{"id":"es-a1-u02-l05","unit_id":"es-a1-u02","position":7,"title_es":"¿De dónde es Marco?","objective_es":"Understand a short introduction and a profile, and introduce yourself.","intro":{"explanation":"Cities like Mexico City, Bogotá and Buenos Aires have many foreign students, and on a language exchange app people introduce themselves like this: name, nationality, city and languages. Remember: un poco de español means a little Spanish.","examples":[{"target":"Me llamo Marco y soy italiano, de Roma.","base":"My name is Marco and I’m Italian, from Rome."},{"target":"Hablo inglés y un poco de español.","base":"I speak English and a little Spanish."}]},"takeaways":["You understand a short profile with name, nationality, city and languages.","You introduce yourself in two or three sentences."]},{"id":"es-a1-u02-listen","unit_id":"es-a1-u02","position":8,"title_es":"Listening practice","objective_es":"Recognize the words and phrases of the unit by ear.","intro":null,"takeaways":[]},{"id":"es-a1-u02-words","unit_id":"es-a1-u02","position":9,"title_es":"Words of the unit","objective_es":"Fix the vocabulary of the unit: recognize it and write it.","intro":null,"takeaways":[]},{"id":"es-a1-u02-final","unit_id":"es-a1-u02","position":10,"title_es":"Final review","objective_es":"Show everything from “Where are you from?”.","intro":null,"takeaways":[]},{"id":"es-a1-u03-l01","unit_id":"es-a1-u03","position":1,"title_es":"Uno, dos, tres","objective_es":"Count from one to six.","intro":{"explanation":"One to six: uno, dos, tres, cuatro, cinco, seis. Every vowel is pronounced: cu-a-tro. The r in tres and cuatro is a quick tap of the tongue, like the tt in American butter. The ei in seis sounds like the ey in they.","examples":[{"target":"Uno, dos, tres, cuatro, cinco, seis.","base":"One, two, three, four, five, six."},{"target":"Hablo dos idiomas.","base":"I speak two languages."}]},"takeaways":["You count from one to six.","You say a number before a noun: dos idiomas."]},{"id":"es-a1-u03-l02","unit_id":"es-a1-u03","position":2,"title_es":"Siete, ocho… ¡veinte!","objective_es":"Count from seven to twelve and say twenty.","intro":{"explanation":"Seven to twelve: siete, ocho, nueve, diez, once, doce. And twenty: veinte. Careful: once is not the English word once — it means eleven. The v in nueve and veinte sounds exactly like a b, and the z in diez sounds like an s. Doce (twelve) has two syllables and dos (two) has one: listen for the e at the end.","examples":[{"target":"Siete, ocho, nueve, diez.","base":"Seven, eight, nine, ten."},{"target":"Once, doce… ¡veinte!","base":"Eleven, twelve… twenty!"}]},"takeaways":["You count from seven to twelve and say veinte.","You remember that once means eleven."]},{"id":"es-a1-u03-rev1","unit_id":"es-a1-u03","position":3,"title_es":"Review 1","objective_es":"Consolidate “Uno, dos, tres” and “Siete, ocho… ¡veinte!”.","intro":null,"takeaways":[]},{"id":"es-a1-u03-l03","unit_id":"es-a1-u03","position":4,"title_es":"Tengo veinte años","objective_es":"Say how old you are with tener.","intro":{"explanation":"In English you are twenty; in Spanish you have twenty years: tengo veinte años. Never say soy veinte. Tengo means I have. Año (year) has an ñ, like the ny in canyon: always write it. For one year, uno becomes un: tengo un año.","examples":[{"target":"Tengo veinte años.","base":"I am twenty years old."},{"target":"Soy estudiante y tengo veinte años.","base":"I’m a student and I’m twenty."}]},"takeaways":["You say your age with tengo + number + años.","You say un año, not uno año."]},{"id":"es-a1-u03-l04","unit_id":"es-a1-u03","position":5,"title_es":"¿Cuántos años tienes?","objective_es":"Ask how old someone is with tú or usted, and talk about other people’s age.","intro":{"explanation":"Tener with other people: tú tienes (to a friend) and él, ella and usted tiene. Notice the change: tengo has a g, and in tienes and tiene the e becomes ie. The only difference between tienes and tiene is the final s: listen for it. To ask a friend: ¿cuántos años tienes? With usted: ¿cuántos años tiene?","examples":[{"target":"¿Cuántos años tienes? — Tengo veinte.","base":"How old are you? — I’m twenty."},{"target":"Valentina tiene seis años.","base":"Valentina is six years old."}]},"takeaways":["You ask a friend ¿cuántos años tienes?","You say yo tengo, tú tienes and él, ella or usted tiene."]},{"id":"es-a1-u03-rev2","unit_id":"es-a1-u03","position":6,"title_es":"Review 2","objective_es":"Consolidate “Tengo veinte años” and “¿Cuántos años tienes?”.","intro":null,"takeaways":[]},{"id":"es-a1-u03-l05","unit_id":"es-a1-u03","position":7,"title_es":"Uno, dos, tres… ¡veinte!","objective_es":"Understand ages and numbers in a conversation and a form.","intro":{"explanation":"In almost every Spanish-speaking country children start primary school at six. On a form you often see nombre (name), nacionalidad (nationality) and edad (age). And remember: un año tiene doce meses — a year has twelve months.","examples":[{"target":"Un año tiene doce meses.","base":"A year has twelve months."},{"target":"Mateo tiene siete años.","base":"Mateo is seven years old."}]},"takeaways":["You understand ages in a short conversation and on a form.","You ask and answer about age with tú and with usted."]},{"id":"es-a1-u03-listen","unit_id":"es-a1-u03","position":8,"title_es":"Listening practice","objective_es":"Recognize the words and phrases of the unit by ear.","intro":null,"takeaways":[]},{"id":"es-a1-u03-words","unit_id":"es-a1-u03","position":9,"title_es":"Words of the unit","objective_es":"Fix the vocabulary of the unit: recognize it and write it.","intro":null,"takeaways":[]},{"id":"es-a1-u03-final","unit_id":"es-a1-u03","position":10,"title_es":"Final review","objective_es":"Show everything from “Numbers and age”.","intro":null,"takeaways":[]},{"id":"es-a1-u04-l01","unit_id":"es-a1-u04","position":1,"title_es":"Mi familia","objective_es":"Name your parents and use el, la, los, las and mi / mis.","intro":{"explanation":"El goes with masculine nouns (el padre) and la with feminine ones (la madre, la familia). In the plural: los and las. A mixed group uses the masculine: los padres means father and mother together. Careful: parents is padres; parientes means relatives. Mi is my, and mis goes before a plural: mis padres. To say whose: el padre de Lucía (Lucía’s father).","examples":[{"target":"Mi familia es de Lima.","base":"My family is from Lima."},{"target":"Mis padres son mexicanos.","base":"My parents are Mexican."}]},"takeaways":["You use el, la, los and las, and los padres for father and mother.","You say mi with one person and mis with more than one."]},{"id":"es-a1-u04-l02","unit_id":"es-a1-u04","position":2,"title_es":"Papá, mamá y hermanos","objective_es":"Talk about your mom, dad, brothers and sisters, and ask about a friend’s.","intro":{"explanation":"Papá and mamá are what people say every day; padre and madre sound more formal. Both have the stress on the last syllable, marked with the accent. Los hermanos means brothers, or brothers and sisters together. Tu is your for someone you call tú (tus before a plural) — with no accent: tu hermana (your sister), but ¿y tú? (and you?). And se llama tells you someone’s name: mi mamá se llama Ana.","examples":[{"target":"Mi mamá se llama Ana.","base":"My mom’s name is Ana."},{"target":"¿Tienes hermanos? — Sí, tengo una hermana.","base":"Do you have any siblings? — Yes, I have a sister."}]},"takeaways":["You say papá, mamá, hermano and hermana.","You ask a friend about family with tu: ¿cómo se llama tu hermano?"]},{"id":"es-a1-u04-rev1","unit_id":"es-a1-u04","position":3,"title_es":"Review 1","objective_es":"Consolidate “Mi familia” and “Papá, mamá y hermanos”.","intro":null,"takeaways":[]},{"id":"es-a1-u04-l03","unit_id":"es-a1-u04","position":4,"title_es":"Abuelos, hijos y su","objective_es":"Talk about grandparents, children and partners, and use su / sus.","intro":{"explanation":"Su means his, her or their, and also your when you speak to someone as usted: su hijo can be his son, her son or your son. Sus goes before a plural: sus hijos. Los hijos means children (sons and daughters); los abuelos, grandparents. In Argentina and Uruguay many families have Italian or Spanish grandparents.","examples":[{"target":"Mi abuelo es italiano.","base":"My grandfather is Italian."},{"target":"Diego tiene una hija y un hijo.","base":"Diego has a daughter and a son."}]},"takeaways":["You talk about abuelos, hijos, esposo and esposa.","You use su / sus for his, her, their and your (usted)."]},{"id":"es-a1-u04-l04","unit_id":"es-a1-u04","position":5,"title_es":"El perro y el gato","objective_es":"Talk about pets and pronounce rr and ll.","intro":{"explanation":"Perro (dog) has a strong, trilled rr; pero (but) has a single quick tap, like the tt in American butter: two different words. In Latin America ll and y sound the same, like the y in yes: ella, se llama, yo. People often ask ¿tienes perro? without un.","examples":[{"target":"Tengo un perro y dos gatos.","base":"I have a dog and two cats."},{"target":"Mi perro se llama Toto.","base":"My dog’s name is Toto."}]},"takeaways":["You say el perro and el gato, and los gatos in the plural.","You trill the rr in perro and say ll like the y in yes."]},{"id":"es-a1-u04-rev2","unit_id":"es-a1-u04","position":6,"title_es":"Review 2","objective_es":"Consolidate “Abuelos, hijos y su” and “El perro y el gato”.","intro":null,"takeaways":[]},{"id":"es-a1-u04-l05","unit_id":"es-a1-u04","position":7,"title_es":"¡Mi familia!","objective_es":"Understand a family post and a conversation, and describe your family.","intro":{"explanation":"In much of Latin America Sunday is a family day: many families meet at the grandparents’ house for a long lunch (in Argentina and Uruguay, often an asado, a barbecue). When you introduce several people, use the plural: mis padres, mis hijos, se llaman.","examples":[{"target":"Mis padres viven en Córdoba.","base":"My parents live in Córdoba."},{"target":"Mis hijos se llaman Mateo y Valentina.","base":"My children are called Mateo and Valentina."}]},"takeaways":["You understand a short post about a family.","You say the names of several people with se llaman."]},{"id":"es-a1-u04-listen","unit_id":"es-a1-u04","position":8,"title_es":"Listening practice","objective_es":"Recognize the words and phrases of the unit by ear.","intro":null,"takeaways":[]},{"id":"es-a1-u04-words","unit_id":"es-a1-u04","position":9,"title_es":"Words of the unit","objective_es":"Fix the vocabulary of the unit: recognize it and write it.","intro":null,"takeaways":[]},{"id":"es-a1-u04-final","unit_id":"es-a1-u04","position":10,"title_es":"Final review","objective_es":"Show everything from “Family”.","intro":null,"takeaways":[]},{"id":"es-a1-u05-l01","unit_id":"es-a1-u05","position":1,"title_es":"¿Qué es esto?","objective_es":"Name school things with un / una and ask what something is.","intro":{"explanation":"Every Spanish noun is masculine or feminine. Nouns in -o are usually masculine and take el (the) or un (a): el libro, un cuaderno. Nouns in -a are usually feminine and take la or una: la mochila, una silla. To ask about a thing, say ¿qué es esto? and answer es un… or es una… A pen is un bolígrafo (in Mexico you will also hear una pluma). The ch in mochila sounds like the ch in English chair.","examples":[{"target":"¿Qué es esto? — Es un libro.","base":"What is this? — It’s a book."},{"target":"Es una mochila.","base":"It’s a backpack."}]},"takeaways":["You ask ¿qué es esto? and answer es un… or es una…","You learn each noun with its article: el libro, la mochila."]},{"id":"es-a1-u05-l02","unit_id":"es-a1-u05","position":2,"title_es":"Unos libros, unas sillas","objective_es":"Make plurals and say how many things there are.","intro":{"explanation":"To make a plural, add -s after a vowel (la silla → las sillas) and -es after a consonant (el celular → los celulares). The articles change too: el → los, la → las, un → unos, una → unas. For one thing you say es; for more than one, son: es una llave, son dos llaves. The ll in silla and llave sounds like the y in yes: SI-ya, YA-ve.","examples":[{"target":"Es una silla. — Son dos sillas.","base":"It’s a chair. — They’re two chairs."},{"target":"Son unas llaves.","base":"They are some keys."}]},"takeaways":["You add -s or -es to make a plural, and the article changes too.","You use es for one thing and son for more than one."]},{"id":"es-a1-u05-rev1","unit_id":"es-a1-u05","position":3,"title_es":"Review 1","objective_es":"Consolidate “¿Qué es esto?” and “Unos libros, unas sillas”.","intro":null,"takeaways":[]},{"id":"es-a1-u05-l03","unit_id":"es-a1-u05","position":4,"title_es":"Los colores","objective_es":"Say what color things are.","intro":{"explanation":"In Spanish the color comes after the noun: un libro rojo (a red book). Colors ending in -o agree with the noun: rojo, roja, rojos, rojas. Colors ending in -e or in a consonant only change in the plural: verde → verdes, azul → azules. To ask about color: ¿de qué color es? The j in rojo is a strong h sound, from the back of the throat.","examples":[{"target":"¿De qué color es la mochila? — Es roja.","base":"What color is the backpack? — It’s red."},{"target":"Un libro azul y un bolígrafo verde.","base":"A blue book and a green pen."}]},"takeaways":["You put the color after the noun: una mochila roja.","You make colors in -o agree: rojo, roja, rojos, rojas."]},{"id":"es-a1-u05-l04","unit_id":"es-a1-u05","position":5,"title_es":"Este libro es grande","objective_es":"Point at things with este / esta and say if they are big or small.","intro":{"explanation":"Este (this) agrees with the noun: este libro, esta mochila, estos libros, estas mochilas. In much of Latin America chico means small (you will also hear pequeño). Grande does not change for feminine: un libro grande, una mesa grande. The ch in chico sounds like the ch in chair, and the ll in silla, llave and amarillo sounds like the y in yes.","examples":[{"target":"Este libro es grande.","base":"This book is big."},{"target":"Esta mochila es chica.","base":"This backpack is small."}]},"takeaways":["You use este, esta, estos or estas depending on the noun.","You say chico for small and grande for big."]},{"id":"es-a1-u05-rev2","unit_id":"es-a1-u05","position":6,"title_es":"Review 2","objective_es":"Consolidate “Los colores” and “Este libro es grande”.","intro":null,"takeaways":[]},{"id":"es-a1-u05-l05","unit_id":"es-a1-u05","position":7,"title_es":"Mi mochila es negra","objective_es":"Describe your things and understand a short notice about a lost object.","intro":{"explanation":"Now you can describe your things: what they are, how many there are, their color and their size. Put it all together with tengo or with es / son: tengo una mochila negra; mi celular es chico y blanco. Remember: the article agrees with the noun, and the adjective comes after it.","examples":[{"target":"Tengo una mochila negra.","base":"I have a black backpack."},{"target":"Mi celular es chico y blanco.","base":"My phone is small and white."}]},"takeaways":["You describe a thing by its color and size.","You understand a short notice about a lost backpack."]},{"id":"es-a1-u05-listen","unit_id":"es-a1-u05","position":8,"title_es":"Listening practice","objective_es":"Recognize the words and phrases of the unit by ear.","intro":null,"takeaways":[]},{"id":"es-a1-u05-words","unit_id":"es-a1-u05","position":9,"title_es":"Words of the unit","objective_es":"Fix the vocabulary of the unit: recognize it and write it.","intro":null,"takeaways":[]},{"id":"es-a1-u05-final","unit_id":"es-a1-u05","position":10,"title_es":"Final review","objective_es":"Show everything from “Things and colors”.","intro":null,"takeaways":[]},{"id":"es-a1-u06-l01","unit_id":"es-a1-u06","position":1,"title_es":"La casa","objective_es":"Name the rooms of a house or an apartment.","intro":{"explanation":"In big Latin American cities many people live in un apartamento (an apartment; in Argentina and Mexico you will also hear departamento, and in Spain piso). The rooms: la sala (the living room), la cocina (the kitchen), el dormitorio (the bedroom) and el baño (the bathroom). The ñ in baño sounds like the ny in canyon, so baño and año are different words.","examples":[{"target":"Mi apartamento es chico.","base":"My apartment is small."},{"target":"La cocina es grande.","base":"The kitchen is big."}]},"takeaways":["You name the rooms: la sala, la cocina, el dormitorio, el baño.","You say apartamento for an apartment."]},{"id":"es-a1-u06-l02","unit_id":"es-a1-u06","position":2,"title_es":"Hay…","objective_es":"Say what there is and what there isn’t in a room.","intro":{"explanation":"Hay means there is and there are, and it never changes: hay una cama, hay dos ventanas. The h is silent, so hay sounds like the English word eye. The negative is no hay. After hay you use un / una, a number or no article, never el or la: hay una cocina (not hay la cocina). With no hay you usually drop the article: no hay puerta.","examples":[{"target":"En el dormitorio hay una cama.","base":"There is a bed in the bedroom."},{"target":"No hay ventanas en el baño.","base":"There are no windows in the bathroom."}]},"takeaways":["You use hay for there is and there are.","You never put el or la after hay."]},{"id":"es-a1-u06-rev1","unit_id":"es-a1-u06","position":3,"title_es":"Review 1","objective_es":"Consolidate “La casa” and “Hay…”.","intro":null,"takeaways":[]},{"id":"es-a1-u06-l03","unit_id":"es-a1-u06","position":4,"title_es":"¿Dónde está?","objective_es":"Ask and say where something is with estar.","intro":{"explanation":"To say where something is, use estar: ¿dónde está la llave? — Está en la mesa. For more than one thing: están. Spanish has two verbs for “to be”: ser for what something is or is like (la cocina es grande) and estar for where it is (la cocina está al lado de la sala). En means in, on or at: en la mesa, en el baño. Hay says that something exists; está says where a specific thing is: hay una mesa, but la mesa está en la cocina.","examples":[{"target":"¿Dónde está el gato? — Está en la cama.","base":"Where is the cat? — It’s on the bed."},{"target":"Mis llaves están en la cocina.","base":"My keys are in the kitchen."}]},"takeaways":["You ask ¿dónde está…? and answer está en…","You use ser for what something is like and estar for where it is."]},{"id":"es-a1-u06-l04","unit_id":"es-a1-u06","position":5,"title_es":"Arriba, debajo, al lado","objective_es":"Place things with prepositions of place.","intro":{"explanation":"Prepositions of place: arriba de (on top of), debajo de (under), al lado de (next to), enfrente de (opposite, across from) and detrás de (behind; in everyday speech you will also hear atrás de). De + el becomes del: al lado del baño. With la nothing changes: al lado de la cocina.","examples":[{"target":"El gato está debajo de la mesa.","base":"The cat is under the table."},{"target":"El baño está al lado del dormitorio.","base":"The bathroom is next to the bedroom."}]},"takeaways":["You place things with arriba de, debajo de, al lado de, enfrente de and detrás de.","You say del, never de el: al lado del baño."]},{"id":"es-a1-u06-rev2","unit_id":"es-a1-u06","position":6,"title_es":"Review 2","objective_es":"Consolidate “¿Dónde está?” and “Arriba, debajo, al lado”.","intro":null,"takeaways":[]},{"id":"es-a1-u06-l05","unit_id":"es-a1-u06","position":7,"title_es":"Mi casa","objective_es":"Understand a description of a home and a conversation about where things are.","intro":{"explanation":"Hay and estar together describe a home: hay dos dormitorios; la cocina está al lado de la sala. Spanish uses a double negative: no hay nada (there is nothing), no hay camas ni mesas (there are no beds or tables).","examples":[{"target":"En mi casa hay tres dormitorios.","base":"There are three bedrooms in my house."},{"target":"No hay nada en la mesa.","base":"There is nothing on the table."}]},"takeaways":["You understand an ad for an apartment.","You follow a short conversation about where things are."]},{"id":"es-a1-u06-listen","unit_id":"es-a1-u06","position":8,"title_es":"Listening practice","objective_es":"Recognize the words and phrases of the unit by ear.","intro":null,"takeaways":[]},{"id":"es-a1-u06-words","unit_id":"es-a1-u06","position":9,"title_es":"Words of the unit","objective_es":"Fix the vocabulary of the unit: recognize it and write it.","intro":null,"takeaways":[]},{"id":"es-a1-u06-final","unit_id":"es-a1-u06","position":10,"title_es":"Final review","objective_es":"Show everything from “At home”.","intro":null,"takeaways":[]},{"id":"es-a1-u07-l01","unit_id":"es-a1-u07","position":1,"title_es":"Café con leche","objective_es":"Name breakfast foods and drinks and ask for them.","intro":{"explanation":"Breakfast changes from country to country: eggs and pan dulce in Mexico, arepas in Colombia, café con leche (coffee with milk) and a croissant in cafés almost everywhere. Con means with. Agua is feminine, but because it starts with a stressed a it takes el: el agua. The g in agua is soft, much softer than the English g, and the ch in leche sounds like the ch in chair.","examples":[{"target":"Un café con leche, por favor.","base":"A coffee with milk, please."},{"target":"Té con leche y pan.","base":"Tea with milk and bread."}]},"takeaways":["You ask for breakfast with por favor: un café con leche, por favor.","You say el agua, even though agua is feminine."]},{"id":"es-a1-u07-l02","unit_id":"es-a1-u07","position":2,"title_es":"Yo como carne","objective_es":"Say what you eat and ask what someone else eats.","intro":{"explanation":"To say what you eat: yo como; to ask a friend: ¿tú comes…? The -o of yo becomes -es for tú: como, comes. You can usually drop tú, because the ending already says who: ¿comes carne? Carne is meat; in Argentina and Uruguay it often means beef grilled at an asado with the family, while in Mexico you may find it in tacos. El pescado is fish as food. Spanish has no word for “some”, and with food in general you drop the article: como carne, no como pescado.","examples":[{"target":"Yo como carne y verduras.","base":"I eat meat and vegetables."},{"target":"¿Tú comes pescado? — No, no como pescado.","base":"Do you eat fish? — No, I don’t eat fish."}]},"takeaways":["You say yo como and ask a friend ¿comes…? (tú comes).","You talk about food in general without an article: como carne."]},{"id":"es-a1-u07-rev1","unit_id":"es-a1-u07","position":3,"title_es":"Review 1","objective_es":"Consolidate “Café con leche” and “Yo como carne”.","intro":null,"takeaways":[]},{"id":"es-a1-u07-l03","unit_id":"es-a1-u07","position":4,"title_es":"Quiero, quisiera","objective_es":"Order politely in a café or a bakery.","intro":{"explanation":"Quiero means I want. In a café or a shop it sounds nicer to say quisiera (I would like) or to add por favor: quisiera un café, por favor. Among friends, people often say ¿me das…? (can you give me…?). To ask a friend what they want, use tú: ¿qué quieres? Querer changes its stem with tú: yo quiero, tú quieres (e → ie). Remember: no word for “some”: quiero pan.","examples":[{"target":"Quisiera un té, por favor.","base":"I’d like a tea, please."},{"target":"¿Qué quieres? — Quiero una manzana.","base":"What do you want? — I want an apple."}]},"takeaways":["You order politely with quisiera… por favor.","You ask a friend ¿qué quieres? (quiero → quieres) or ¿me das…?"]},{"id":"es-a1-u07-l04","unit_id":"es-a1-u07","position":5,"title_es":"Tomo café","objective_es":"Say what you drink and how much.","intro":{"explanation":"To drink you can use tomar or beber. In Latin America tomar is the everyday verb for drinks: tomo café, tomo agua; beber (yo bebo, tú bebes) is understood everywhere and is very common in Spain. With tú: ¿tomas café? ¿bebes agua? In Argentina, Uruguay and Paraguay people also share el mate, a herbal tea drunk from a gourd through a metal straw and passed round the group. Mucho agrees with the noun: mucho café, mucha agua (agua is feminine). Un poco de (a little) never changes: un poco de leche. Compare the soft g in agua with the strong j in jugo (juice), like a strong h.","examples":[{"target":"¿Tomas café? — Sí, tomo mucho café.","base":"Do you drink coffee? — Yes, I drink a lot of coffee."},{"target":"Bebo un poco de leche.","base":"I drink a little milk."}]},"takeaways":["You say tomo (or bebo) for I drink and ask a friend ¿tomas…?","You use mucho / mucha and un poco de for quantities."]},{"id":"es-a1-u07-rev2","unit_id":"es-a1-u07","position":6,"title_es":"Review 2","objective_es":"Consolidate “Quiero, quisiera” and “Tomo café”.","intro":null,"takeaways":[]},{"id":"es-a1-u07-l05","unit_id":"es-a1-u07","position":7,"title_es":"En el café","objective_es":"Understand an order in a café and a breakfast menu.","intro":{"explanation":"In Latin America the waiter is el mesero or la mesera (el camarero in Spain). Order with quisiera… por favor. Meal times vary: in Spain and Argentina dinner is late, often after nine; in Mexico la comida, around two or three, is the big meal of the day. A waiter usually speaks to you with usted: ¿qué quiere tomar? (quiere, not quieres).","examples":[{"target":"Quisiera un café con leche y dos croissants.","base":"I’d like a coffee with milk and two croissants."},{"target":"Un poco de agua, por favor.","base":"A little water, please."}]},"takeaways":["You understand a short order in a café.","You read a simple breakfast menu."]},{"id":"es-a1-u07-listen","unit_id":"es-a1-u07","position":8,"title_es":"Listening practice","objective_es":"Recognize the words and phrases of the unit by ear.","intro":null,"takeaways":[]},{"id":"es-a1-u07-words","unit_id":"es-a1-u07","position":9,"title_es":"Words of the unit","objective_es":"Fix the vocabulary of the unit: recognize it and write it.","intro":null,"takeaways":[]},{"id":"es-a1-u07-final","unit_id":"es-a1-u07","position":10,"title_es":"Final review","objective_es":"Show everything from “Food and drinks”.","intro":null,"takeaways":[]},{"id":"es-a1-u08-l01","unit_id":"es-a1-u08","position":1,"title_es":"La mañana, la tarde, la noche","objective_es":"Talk about the parts of the day and the meals.","intro":{"explanation":"La mañana is the morning, la tarde the afternoon and la noche the evening or night. To say “in the morning”, say por la mañana (por la tarde, por la noche); in Argentina and Uruguay you will also hear a la mañana. The meals: el desayuno (breakfast), el almuerzo (lunch; in Mexico people usually call the midday meal la comida) and la cena (dinner). Meal times change from country to country: in Spain and Argentina dinner is late, often after nine in the evening. Careful: la mañana is the morning, but mañana on its own means tomorrow. The ñ sounds like the ny in canyon.","examples":[{"target":"Tomo café por la mañana.","base":"I drink coffee in the morning."},{"target":"La cena es por la noche.","base":"Dinner is in the evening."}]},"takeaways":["You say when you do something with por la mañana, por la tarde and por la noche.","You name the meals: el desayuno, el almuerzo and la cena."]},{"id":"es-a1-u08-l02","unit_id":"es-a1-u08","position":2,"title_es":"Me levanto, me acuesto","objective_es":"Say when you get up and go to bed, and in what order you do things.","intro":{"explanation":"Some verbs come with me, te or se: they are reflexive, a bit like “get yourself up”. Me levanto is I get up and me acuesto is I go to bed; me ducho is I take a shower. With tú: te levantas, te acuestas. Notice the ue: acostarse changes o to ue in yo, tú and él / ella (me acuesto, te acuestas, se acuesta). With él, ella or usted: se levanta, se acuesta. To put things in order: primero (first) and después (then, afterwards). Two handy extras: tarde also means late (me acuesto tarde), and desayuno also means I have breakfast.","examples":[{"target":"Primero me levanto, después me ducho.","base":"First I get up, then I take a shower."},{"target":"Me acuesto muy tarde.","base":"I go to bed very late."}]},"takeaways":["You use me levanto and me acuesto, and te levantas, te acuestas with tú.","You order your day with primero and después."]},{"id":"es-a1-u08-rev1","unit_id":"es-a1-u08","position":3,"title_es":"Review 1","objective_es":"Consolidate “La mañana, la tarde, la noche” and “Me levanto, me acuesto”.","intro":null,"takeaways":[]},{"id":"es-a1-u08-l03","unit_id":"es-a1-u08","position":4,"title_es":"Trabajo, miro, escucho","objective_es":"Say what you and others do, with yo, tú and él or ella, and how often.","intro":{"explanation":"Verbs ending in -ar (trabajar, mirar, escuchar) change their ending for each person: yo trabajo, tú trabajas, él, ella or usted trabaja. The stress stays in the same place (tra-BA-jo, tra-BA-jas, tra-BA-ja), so listen for the ending: -o is I, -as is you, -a is he, she or usted. Mirar means to watch or look at and escuchar to listen to, with no extra word for “at” or “to”: miro la tele, escucho música. Siempre (always) and a veces (sometimes) usually go before the verb.","examples":[{"target":"Siempre escucho música.","base":"I always listen to music."},{"target":"¿Trabajas en Bogotá?","base":"Do you work in Bogotá?"}]},"takeaways":["You conjugate -ar verbs for yo, tú and él or ella: trabajo, trabajas, trabaja.","You say how often with siempre and a veces."]},{"id":"es-a1-u08-l04","unit_id":"es-a1-u08","position":5,"title_es":"Nosotros, ustedes, ellos","objective_es":"Talk about what we, you all and they do, with -ar, -er and -ir verbs.","intro":{"explanation":"The plural persons are nosotros (we; nosotras if they are all women), ustedes (you all) and ellos (they; ellas for women). In Latin America ustedes is the plural of both tú and usted (in Spain friends say vosotros, which this course does not practise), and ustedes and ellos share the same verb form. -ar: trabajamos, trabajan. Verbs in -er and -ir follow the same idea: comer → como, comes, come, comemos, comen; vivir → vivo, vives, vive, vivimos, viven. Todos los días means every day.","examples":[{"target":"Nosotros comemos en casa todos los días.","base":"We eat at home every day."},{"target":"¿Ustedes viven en Guadalajara? — No, vivimos en Monterrey.","base":"Do you all live in Guadalajara? — No, we live in Monterrey."}]},"takeaways":["You use nosotros, ustedes and ellos with their endings: -amos / -emos / -imos and -an / -en.","You say that something happens every day with todos los días."]},{"id":"es-a1-u08-rev2","unit_id":"es-a1-u08","position":6,"title_es":"Review 2","objective_es":"Consolidate “Trabajo, miro, escucho” and “Nosotros, ustedes, ellos”.","intro":null,"takeaways":[]},{"id":"es-a1-u08-l05","unit_id":"es-a1-u08","position":7,"title_es":"Mi día","objective_es":"Understand and tell a short description of someone’s day.","intro":{"explanation":"To tell your day, put the actions in order with primero and después, and add when (por la mañana, por la tarde, por la noche) and how often (siempre, a veces, todos los días). Routines change from country to country: in Mexico the big meal (la comida) is around two or three in the afternoon, and in Spain and Argentina dinner is very late.","examples":[{"target":"Todos los días me levanto temprano y tomo café.","base":"Every day I get up early and drink café."},{"target":"Por la noche ceno y después me acuesto.","base":"In the evening I have dinner and then I go to bed."}]},"takeaways":["You understand a short text about someone’s routine.","You tell your own day in order, with when and how often."]},{"id":"es-a1-u08-listen","unit_id":"es-a1-u08","position":8,"title_es":"Listening practice","objective_es":"Recognize the words and phrases of the unit by ear.","intro":null,"takeaways":[]},{"id":"es-a1-u08-words","unit_id":"es-a1-u08","position":9,"title_es":"Words of the unit","objective_es":"Fix the vocabulary of the unit: recognize it and write it.","intro":null,"takeaways":[]},{"id":"es-a1-u08-final","unit_id":"es-a1-u08","position":10,"title_es":"Final review","objective_es":"Show everything from “My day”.","intro":null,"takeaways":[]},{"id":"es-a1-u09-l01","unit_id":"es-a1-u09","position":1,"title_es":"¿Qué hora es?","objective_es":"Ask the time and say it with o’clock, quarter past and half past.","intro":{"explanation":"¿Qué hora es? asks the time. For one o’clock say es la una; for every other hour, son las + number: son las dos, son las ocho. The la and las are there because they refer to la hora (the time). Add y cuarto for quarter past and y media for half past: son las ocho y media. To ask someone informally: ¿tienes la hora? (tener: yo tengo, tú tienes); to a stranger, with usted: ¿tiene la hora? Careful with dos (two) and doce (twelve): listen for the c.","examples":[{"target":"¿Qué hora es? — Es la una.","base":"What time is it? — It’s one o’clock."},{"target":"Son las ocho y media.","base":"It’s half past eight."}]},"takeaways":["You ask ¿qué hora es? and answer es la una or son las dos.","You add y cuarto and y media."]},{"id":"es-a1-u09-l02","unit_id":"es-a1-u09","position":2,"title_es":"A las ocho","objective_es":"Say at what time you do things, with quarter to, noon and midnight.","intro":{"explanation":"After half past, count back with menos: son las nueve menos cuarto (quarter to nine). Twelve o’clock is el mediodía (noon) or la medianoche (midnight). To ask when something happens: ¿a qué hora…? The answer uses a: a la una, a las ocho, al mediodía (a + el becomes al). Add de la mañana, de la tarde or de la noche to be clear: a las diez de la noche.","examples":[{"target":"¿A qué hora te levantas? — A las siete.","base":"What time do you get up? — At seven."},{"target":"Almuerzo al mediodía.","base":"I have lunch at noon."}]},"takeaways":["You ask ¿a qué hora? and answer a la una or a las ocho.","You use menos cuarto, el mediodía and la medianoche."]},{"id":"es-a1-u09-rev1","unit_id":"es-a1-u09","position":3,"title_es":"Review 1","objective_es":"Consolidate “¿Qué hora es?” and “A las ocho”.","intro":null,"takeaways":[]},{"id":"es-a1-u09-l03","unit_id":"es-a1-u09","position":4,"title_es":"Lunes, martes, miércoles","objective_es":"Name the weekdays and say on which day you do something.","intro":{"explanation":"The days of the week are masculine and written in lower case: lunes, martes, miércoles, jueves. Use el for one specific day (el lunes = on Monday) and los for something you do every week (los lunes = on Mondays); there is no word for “on”. These days don’t change in the plural: el martes, los martes. De lunes a jueves means from Monday to Thursday. La semana is the week. Miércoles carries an accent because the stress falls on mié.","examples":[{"target":"El lunes trabajo en casa.","base":"On Monday I work at home."},{"target":"Los jueves como con mi abuela.","base":"On Thursdays I eat with my grandmother."}]},"takeaways":["You name the days from lunes to jueves.","You say el lunes for one day and los lunes for every week."]},{"id":"es-a1-u09-l04","unit_id":"es-a1-u09","position":5,"title_es":"El fin de semana","objective_es":"Talk about Friday and the weekend and read a timetable.","intro":{"explanation":"Viernes is Friday, and the weekend, el fin de semana, is sábado and domingo. In Spain and Argentina people often shorten it to el finde (informal). Sábado and domingo add an s in the plural: los sábados, los domingos. In many Spanish-speaking countries Sunday is a family day, often with a long lunch.","examples":[{"target":"El sábado me levanto tarde.","base":"On Saturday I get up late."},{"target":"Los domingos como con mi familia.","base":"On Sundays I eat with my family."}]},"takeaways":["You name viernes, sábado and domingo and say el fin de semana.","You understand days and times in a timetable."]},{"id":"es-a1-u09-rev2","unit_id":"es-a1-u09","position":6,"title_es":"Review 2","objective_es":"Consolidate “Lunes, martes, miércoles” and “El fin de semana”.","intro":null,"takeaways":[]},{"id":"es-a1-u09-l05","unit_id":"es-a1-u09","position":7,"title_es":"Hoy y mañana","objective_es":"Say what day it is today and tomorrow, and follow a short conversation about times.","intro":{"explanation":"Hoy is today and mañana is tomorrow. Don’t mix up mañana (tomorrow) and la mañana (the morning): mañana por la mañana is tomorrow morning. Listen to the melody of questions: a yes/no question goes up at the end (¿Hoy trabajas?), while a question with qué or a qué hora usually goes down (¿A qué hora trabajas?).","examples":[{"target":"Hoy es viernes.","base":"Today is Friday."},{"target":"Mañana por la mañana trabajo.","base":"Tomorrow morning I work."}]},"takeaways":["You say hoy es… and mañana es…","You tell mañana (tomorrow) apart from la mañana (the morning)."]},{"id":"es-a1-u09-listen","unit_id":"es-a1-u09","position":8,"title_es":"Listening practice","objective_es":"Recognize the words and phrases of the unit by ear.","intro":null,"takeaways":[]},{"id":"es-a1-u09-words","unit_id":"es-a1-u09","position":9,"title_es":"Words of the unit","objective_es":"Fix the vocabulary of the unit: recognize it and write it.","intro":null,"takeaways":[]},{"id":"es-a1-u09-final","unit_id":"es-a1-u09","position":10,"title_es":"Final review","objective_es":"Show everything from “Time and days”.","intro":null,"takeaways":[]},{"id":"es-a1-u10-l01","unit_id":"es-a1-u10","position":1,"title_es":"Voy, vas, va","objective_es":"Say where you, a friend or someone else is going.","intro":{"explanation":"Ir (to go) is irregular: yo voy, tú vas, él, ella or usted va. To say where, use a + place. A + el always becomes al: voy al cine, voy al museo. With la it stays the same: voy a la farmacia. The same verb works for “I go” and “I’m going”: voy al cine can mean both. The v in voy and vas sounds just like a b.","examples":[{"target":"Voy al cine.","base":"I’m going to the cinema."},{"target":"¿Vas al museo? — No, voy al cine.","base":"Are you going to the museum? — No, I’m going to the cinema."}]},"takeaways":["You say voy, vas and va + a + place.","You join a + el into al: voy al cine."]},{"id":"es-a1-u10-l02","unit_id":"es-a1-u10","position":2,"title_es":"Vamos, van","objective_es":"Say where we, you all and they are going: the bakery, the supermarket, the bank.","intro":{"explanation":"In the plural: nosotros vamos, ustedes and ellos van. In Latin America ustedes is the only plural “you” (in Spain friends say vosotros, which you only need to recognise). Vamos also means let’s go: ¡vamos al cine! In your barrio (neighbourhood) you go to la panadería for bread, to el supermercado for everything else and to el banco for money matters.","examples":[{"target":"Vamos a la panadería.","base":"We’re going to the bakery."},{"target":"Ellos van al supermercado.","base":"They’re going to the supermarket."}]},"takeaways":["You say vamos for we and van for ustedes, ellos and ellas.","You name la panadería, el supermercado and el banco."]},{"id":"es-a1-u10-rev1","unit_id":"es-a1-u10","position":3,"title_es":"Review 1","objective_es":"Consolidate “Voy, vas, va” and “Vamos, van”.","intro":null,"takeaways":[]},{"id":"es-a1-u10-l03","unit_id":"es-a1-u10","position":4,"title_es":"¿Dónde está la farmacia?","objective_es":"Ask where a place is and say if it is near or far.","intro":{"explanation":"To ask for a place, use está, as in unit 6: ¿dónde está la farmacia? Answer está cerca (it’s near) or está lejos (it’s far); to say near what: cerca de la estación. De + el becomes del: cerca del banco. With a stranger, start with disculpe (excuse me, formal) or perdón. In many Latin American cities distances are given in cuadras (blocks): está a dos cuadras.","examples":[{"target":"Disculpe, ¿dónde está la farmacia?","base":"Excuse me, where is the pharmacy?"},{"target":"La estación está cerca del banco.","base":"The station is near the bank."}]},"takeaways":["You ask ¿dónde está…? and answer with cerca or lejos.","You join de + el into del: cerca del banco."]},{"id":"es-a1-u10-l04","unit_id":"es-a1-u10","position":5,"title_es":"Dobla a la derecha","objective_es":"Give and follow simple directions with tú and usted.","intro":{"explanation":"To give directions to a friend, use the tú command. For most verbs it is the same as the él / ella form of the present: él dobla → ¡dobla! (turn). Seguir (to keep going) changes e to i (sigo, sigues, sigue), so the command is sigue. With usted the vowel swaps: doble, siga. You will also hear gira (turn). A la derecha is on the right, a la izquierda on the left, and derecho (or todo derecho) is straight ahead: don’t mix up derecho (straight) and derecha (right). Pronunciation: the single r in derecha is a quick tap, like the tt in American butter, while rr, as in perro or barrio, is a strong trill. The z in izquierda sounds like an s.","examples":[{"target":"Sigue derecho y dobla a la izquierda.","base":"Go straight ahead and turn left."},{"target":"Doble a la derecha, señora.","base":"Turn right, madam."}]},"takeaways":["You give directions with dobla and sigue (tú), and doble and siga with usted.","You say a la derecha, a la izquierda and derecho."]},{"id":"es-a1-u10-rev2","unit_id":"es-a1-u10","position":6,"title_es":"Review 2","objective_es":"Consolidate “¿Dónde está la farmacia?” and “Dobla a la derecha”.","intro":null,"takeaways":[]},{"id":"es-a1-u10-l05","unit_id":"es-a1-u10","position":7,"title_es":"En el barrio","objective_es":"Understand directions and plans in a conversation and a message.","intro":{"explanation":"Now put it all together: where you are going (voy al cine), where a place is (cerca de la estación, enfrente del banco) and how to get there (sigue derecho, dobla a la izquierda). Remember from unit 6: al lado de (next to) and enfrente de (opposite).","examples":[{"target":"La farmacia del barrio está cerca.","base":"The local pharmacy is nearby."},{"target":"El cine está enfrente del museo.","base":"The cinema is opposite the museum."}]},"takeaways":["You understand simple directions in a conversation.","You say where you are going and where a place is."]},{"id":"es-a1-u10-listen","unit_id":"es-a1-u10","position":8,"title_es":"Listening practice","objective_es":"Recognize the words and phrases of the unit by ear.","intro":null,"takeaways":[]},{"id":"es-a1-u10-words","unit_id":"es-a1-u10","position":9,"title_es":"Words of the unit","objective_es":"Fix the vocabulary of the unit: recognize it and write it.","intro":null,"takeaways":[]},{"id":"es-a1-u10-final","unit_id":"es-a1-u10","position":10,"title_es":"Final review","objective_es":"Show everything from “Around town”.","intro":null,"takeaways":[]},{"id":"es-a1-u11-l01","unit_id":"es-a1-u11","position":1,"title_es":"Me gusta…","objective_es":"Say what you like and don’t like, and ask a friend.","intro":{"explanation":"To say you like something: me gusta + the thing, with its article: me gusta la música, me gusta el fútbol (English drops the article; Spanish keeps it). To say you don’t: no me gusta. To ask a friend: ¿te gusta…? A strong no: no me gusta para nada (I don’t like it at all). The g in gusta is hard, like the g in go.","examples":[{"target":"Me gusta la música.","base":"I like music."},{"target":"¿Te gusta el fútbol? — No, para nada.","base":"Do you like football? — No, not at all."}]},"takeaways":["You say what you like with me gusta + el / la + noun.","You ask a friend ¿te gusta…? and answer no, para nada."]},{"id":"es-a1-u11-l02","unit_id":"es-a1-u11","position":2,"title_es":"Me gustan, me encanta, odio","objective_es":"Talk about things you like in the plural, and say you love or hate something.","intro":{"explanation":"When you like several things, gustar goes plural: me gustan los perros. Me encanta (I love) works the same way: me encanta el café, me encantan los libros. Odio (I hate) is a normal verb: odio el té. For he or she, use le: a mi papá le gusta el fútbol. Listen to the end of the word: gusta or gustan.","examples":[{"target":"Me gustan los perros.","base":"I like dogs."},{"target":"Me encanta el café, pero odio el té.","base":"I love coffee, but I hate tea."}]},"takeaways":["You use me gustan and me encantan with plural things.","You say you hate something with odio."]},{"id":"es-a1-u11-rev1","unit_id":"es-a1-u11","position":3,"title_es":"Review 1","objective_es":"Consolidate “Me gusta…” and “Me gustan, me encanta, odio”.","intro":null,"takeaways":[]},{"id":"es-a1-u11-l03","unit_id":"es-a1-u11","position":4,"title_es":"Me gusta leer","objective_es":"Talk about free-time activities with me gusta + a verb.","intro":{"explanation":"To say you like doing something, use the infinitive (the basic form of the verb, ending in -ar, -er or -ir) and always gusta, never gustan: me gusta leer, me gusta bailar y cocinar. English uses the -ing form (I like reading); Spanish uses the infinitive. Your free time is el tiempo libre. Every country has its dances: salsa in Cali, tango in Buenos Aires, cumbia almost everywhere.","examples":[{"target":"Me gusta leer.","base":"I like reading."},{"target":"En mi tiempo libre me encanta bailar.","base":"In my free time I love dancing."}]},"takeaways":["You say what you like doing with me gusta + infinitive.","You talk about your free time: en mi tiempo libre…"]},{"id":"es-a1-u11-l04","unit_id":"es-a1-u11","position":5,"title_es":"Juego al fútbol","objective_es":"Say which sports and instruments you play, with jugar and tocar.","intro":{"explanation":"English “play” is two verbs in Spanish: jugar for games and sports (juego al fútbol: a + el becomes al) and tocar for instruments (toco la guitarra). Jugar changes u to ue: yo juego, tú juegas, él / ella / usted juega (only nosotros keeps the u: jugamos). In Mexico people often drop the al: juego fútbol. Pronunciation: in guitarra the u is silent and the g is hard, like the g in give; the j in juego and jugar sounds like a strong English h.","examples":[{"target":"Juego al fútbol los domingos.","base":"I play football on Sundays."},{"target":"Mi hermana toca la guitarra.","base":"My sister plays the guitar."}]},"takeaways":["You play sports with jugar al… (juego, tú juegas).","You play instruments with tocar: toco la guitarra."]},{"id":"es-a1-u11-rev2","unit_id":"es-a1-u11","position":6,"title_es":"Review 2","objective_es":"Consolidate “Me gusta leer” and “Juego al fútbol”.","intro":null,"takeaways":[]},{"id":"es-a1-u11-l05","unit_id":"es-a1-u11","position":7,"title_es":"Prefiero salir","objective_es":"Say what you prefer, talk about going out with friends, and understand a post.","intro":{"explanation":"Prefiero (I prefer) changes e to ie, and so does the tú form: yo prefiero, tú prefieres, él / ella / usted prefiere. To ask a friend: ¿prefieres el té o el café? Salir is to go out: salir con amigos (con = with). In many Spanish-speaking cities, from Madrid to Bogotá, people go out with friends late, especially on Fridays and Saturdays.","examples":[{"target":"Prefiero salir con mis amigos.","base":"I prefer going out with my friends."},{"target":"¿Prefieres el té o el café?","base":"Do you prefer tea or coffee?"}]},"takeaways":["You say what you prefer with prefiero and ask a friend ¿prefieres…?","You talk about going out with friends: salir con amigos."]},{"id":"es-a1-u11-listen","unit_id":"es-a1-u11","position":8,"title_es":"Listening practice","objective_es":"Recognize the words and phrases of the unit by ear.","intro":null,"takeaways":[]},{"id":"es-a1-u11-words","unit_id":"es-a1-u11","position":9,"title_es":"Words of the unit","objective_es":"Fix the vocabulary of the unit: recognize it and write it.","intro":null,"takeaways":[]},{"id":"es-a1-u11-final","unit_id":"es-a1-u11","position":10,"title_es":"Final review","objective_es":"Show everything from “Likes and free time”.","intro":null,"takeaways":[]},{"id":"es-a1-u12-l01","unit_id":"es-a1-u12","position":1,"title_es":"¿Quién? ¿Qué? ¿Cuál?","objective_es":"Ask who someone is, what something is and which one.","intro":{"explanation":"Question words always have a written accent, and the question opens with ¿: ¿quién? (who), ¿qué? (what), ¿cuál? (which one). Cuál is for choosing between things: ¿cuál es tu libro? In questions with a question word, the voice usually goes down at the end, not up as in a yes/no question.","examples":[{"target":"¿Quién es ella? — Es mi mamá.","base":"Who is she? — She’s my mom."},{"target":"¿Cuál es tu mochila? — La roja.","base":"Which one is your backpack? — The red one."}]},"takeaways":["You ask with ¿quién?, ¿qué? and ¿cuál?, always with an accent.","You open every question with ¿ and close it with ?."]},{"id":"es-a1-u12-l02","unit_id":"es-a1-u12","position":2,"title_es":"¿Por qué? Porque…","objective_es":"Ask how something is and why, and give a reason with porque.","intro":{"explanation":"¿Cómo es…? asks what something or someone is like: ¿cómo es tu casa? — Es grande. ¿Por qué? (two words, accent on qué) means why; the answer starts with porque (one word, no accent, stress on por): because. You hear the difference in the stress: por QUÉ, POR-que.","examples":[{"target":"¿Cómo es tu ciudad? — Es muy grande.","base":"What is your city like? — It’s very big."},{"target":"¿Por qué tomas café? — Porque me encanta.","base":"Why do you drink coffee? — Because I love it."}]},"takeaways":["You ask why with ¿por qué? and answer with porque.","You ask what something is like with ¿cómo es…?"]},{"id":"es-a1-u12-rev1","unit_id":"es-a1-u12","position":3,"title_es":"Review 1","objective_es":"Consolidate “¿Quién? ¿Qué? ¿Cuál?” and “¿Por qué? Porque…”.","intro":null,"takeaways":[]},{"id":"es-a1-u12-l03","unit_id":"es-a1-u12","position":4,"title_es":"Trece, quince, treinta…","objective_es":"Count from 13 to 100 and ask how many.","intro":{"explanation":"13 is trece and 15 is quince. The tens: treinta (30), cuarenta (40), cincuenta (50); in between you add y: treinta y uno, cuarenta y cinco. 100 is cien, but from 101 it is ciento: ciento veinte. ¿Cuánto? agrees with the noun: ¿cuántos hermanos?, ¿cuántas sillas?, ¿cuánta agua? The c in cinco and cincuenta sounds like s; the qu in quince sounds like k.","examples":[{"target":"Mi papá tiene cuarenta y cinco años.","base":"My dad is forty-five."},{"target":"¿Cuántas sillas hay? — Hay treinta.","base":"How many chairs are there? — There are thirty."},{"target":"Hay cien libros. Hay ciento veinte cuadernos.","base":"There are a hundred books. There are a hundred and twenty notebooks."}]},"takeaways":["You count 13, 15 and in tens up to cien.","You ask how many with ¿cuántos? or ¿cuántas?"]},{"id":"es-a1-u12-l04","unit_id":"es-a1-u12","position":5,"title_es":"¿Cuánto cuesta?","objective_es":"Ask for prices, say if something is expensive or cheap and say what you are looking for.","intro":{"explanation":"To ask a price: ¿cuánto cuesta? (for several things, ¿cuánto cuestan?). Caro (expensive) and barato (cheap) agree with the thing: el libro es caro, la camiseta es barata. Busco means I’m looking for, with no extra word for “for”; with tú it is buscas. Mexico, Colombia, Chile and Argentina all use the peso (written with $), but its value is very different in each country: in Colombia or Chile prices are often in the thousands (mil is a thousand: treinta mil pesos).","examples":[{"target":"¿Cuánto cuesta la camiseta? — Cuesta treinta mil pesos.","base":"How much is the T-shirt? — It costs thirty thousand pesos."},{"target":"Busco una mochila barata.","base":"I’m looking for a cheap backpack."}]},"takeaways":["You ask ¿cuánto cuesta? and understand prices in pesos.","You say busco… and es caro / es barato."]},{"id":"es-a1-u12-rev2","unit_id":"es-a1-u12","position":6,"title_es":"Review 2","objective_es":"Consolidate “Trece, quince, treinta…” and “¿Cuánto cuesta?”.","intro":null,"takeaways":[]},{"id":"es-a1-u12-l05","unit_id":"es-a1-u12","position":7,"title_es":"En el negocio","objective_es":"Understand prices in a conversation and on a shop sign.","intro":{"explanation":"In most Spanish-speaking countries people greet when they walk into a small shop: buenos días or buenas tardes. Shop assistants often use usted with customers (¿qué busca?). A shop is el negocio or la tienda. On signs, prices are written with $, the peso sign, which looks like the dollar sign.","examples":[{"target":"Buenas tardes. ¿Cuánto cuesta el queso?","base":"Good afternoon. How much is the cheese?"},{"target":"Hoy todo es muy barato.","base":"Today everything is very cheap."}]},"takeaways":["You understand prices and question words in a short conversation.","You read a shop sign with prices in pesos."]},{"id":"es-a1-u12-listen","unit_id":"es-a1-u12","position":8,"title_es":"Listening practice","objective_es":"Recognize the words and phrases of the unit by ear.","intro":null,"takeaways":[]},{"id":"es-a1-u12-words","unit_id":"es-a1-u12","position":9,"title_es":"Words of the unit","objective_es":"Fix the vocabulary of the unit: recognize it and write it.","intro":null,"takeaways":[]},{"id":"es-a1-u12-final","unit_id":"es-a1-u12","position":10,"title_es":"Final review","objective_es":"Show everything from “Questions and shopping”.","intro":null,"takeaways":[]},{"id":"es-a1-u13-l01","unit_id":"es-a1-u13","position":1,"title_es":"¿A qué te dedicas?","objective_es":"Ask what someone does and say your job.","intro":{"explanation":"To ask a friend what they do: ¿a qué te dedicas? (literally “what do you dedicate yourself to?”). With usted, for someone older or in a formal situation: ¿a qué se dedica? Answer with soy + profession and no article: soy médico, soy profesora. English says “I’m a doctor”, but in Spanish un or una is wrong here. El trabajo is your job or work. The j in trabajo sounds like a strong English h, from the back of the throat.","examples":[{"target":"¿A qué te dedicas? — Soy abogado.","base":"What do you do? — I’m a lawyer."},{"target":"Mi papá es médico.","base":"My dad is a doctor."}]},"takeaways":["You ask ¿a qué te dedicas? (usted: ¿a qué se dedica?) and answer soy + profession.","You don’t use un or una before a profession after ser."]},{"id":"es-a1-u13-l02","unit_id":"es-a1-u13","position":2,"title_es":"Enfermero, enfermera","objective_es":"Say jobs in the masculine and the feminine.","intro":{"explanation":"Most jobs change -o to -a for a woman: enfermero / enfermera, ingeniero / ingeniera, mesero / mesera. Jobs ending in -or add -a: vendedor / vendedora, profesor / profesora. El mesero (waiter) is the usual word in Mexico and much of Latin America; you will also hear el camarero in Spain and el mozo in Argentina. In ingeniero, the g before e sounds like the Spanish j, a strong h.","examples":[{"target":"Mi hermana es enfermera.","base":"My sister is a nurse."},{"target":"¡Mesero, un café, por favor!","base":"Waiter, a coffee, please!"}]},"takeaways":["You change -o to -a, or add -a after -or, for a woman’s job.","You call the waiter el mesero (la mesera for a woman)."]},{"id":"es-a1-u13-rev1","unit_id":"es-a1-u13","position":3,"title_es":"Review 1","objective_es":"Consolidate “¿A qué te dedicas?” and “Enfermero, enfermera”.","intro":null,"takeaways":[]},{"id":"es-a1-u13-l03","unit_id":"es-a1-u13","position":4,"title_es":"En la oficina, en el hospital","objective_es":"Say where you work or study.","intro":{"explanation":"Trabajo en + place: trabajo en una oficina, en un hospital. Estudio means I study (tú estudias, you study). La escuela is school (for children). A university is made of facultades (schools or faculties: medicine, law…), so students often say estudio en la facultad for “I study at university”. English says “at school” or “at university”; Spanish uses en. To ask a friend where they work: ¿dónde trabajas?","examples":[{"target":"Trabajo en una oficina.","base":"I work in an office."},{"target":"Estudio en la facultad.","base":"I study at university."}]},"takeaways":["You say where you work with trabajo en…","You say where you study with estudio en…"]},{"id":"es-a1-u13-l04","unit_id":"es-a1-u13","position":5,"title_es":"Somos, tenemos","objective_es":"Talk about two or more people with somos, son, tenemos and tienen.","intro":{"explanation":"Ser in the plural: nosotros somos (we are), ellos / ellas son (they are). Tener: tenemos (we have), tienen (they have). Ustedes (you, plural) uses the same forms as ellos: ustedes son, ustedes tienen. In Latin America ustedes is the only plural “you”, for friends and strangers alike (in Spain, friends use vosotros, which you don’t need here). Compare the singular: yo soy, tú eres; yo tengo, tú tienes. Jobs go plural too: somos médicos, son profesoras.","examples":[{"target":"Somos estudiantes.","base":"We are students."},{"target":"Ellos son ingenieros. Tienen dos hijos.","base":"They are engineers. They have two children."}]},"takeaways":["You say we are and they are with somos and son.","You say we have and they have with tenemos and tienen."]},{"id":"es-a1-u13-rev2","unit_id":"es-a1-u13","position":6,"title_es":"Review 2","objective_es":"Consolidate “En la oficina, en el hospital” and “Somos, tenemos”.","intro":null,"takeaways":[]},{"id":"es-a1-u13-l05","unit_id":"es-a1-u13","position":7,"title_es":"Empiezo a las nueve","objective_es":"Say what time you start and finish, and understand people talking about their work.","intro":{"explanation":"Empezar (to start) changes e to ie: yo empiezo, tú empiezas, él / ella / usted empieza. The same ie appears in every form where the stress falls on the stem (only nosotros empezamos keeps the e). Terminar (to finish) and estudiar (to study) are regular: termino, terminas, termina; estudio, estudias, estudia. With a time, use a las: empiezo a las nueve, termino a las cinco.","examples":[{"target":"Empiezo a las nueve y termino a las seis.","base":"I start at nine and finish at six."},{"target":"¿A qué hora empiezas?","base":"What time do you start?"}]},"takeaways":["You say when you start and finish with empiezo and termino, and ask ¿a qué hora empiezas?","You understand a short text about someone’s job and studies."]},{"id":"es-a1-u13-listen","unit_id":"es-a1-u13","position":8,"title_es":"Listening practice","objective_es":"Recognize the words and phrases of the unit by ear.","intro":null,"takeaways":[]},{"id":"es-a1-u13-words","unit_id":"es-a1-u13","position":9,"title_es":"Words of the unit","objective_es":"Fix the vocabulary of the unit: recognize it and write it.","intro":null,"takeaways":[]},{"id":"es-a1-u13-final","unit_id":"es-a1-u13","position":10,"title_es":"Final review","objective_es":"Show everything from “Work and studies”.","intro":null,"takeaways":[]},{"id":"es-a1-u14-l01","unit_id":"es-a1-u14","position":1,"title_es":"¿Cómo es?","objective_es":"Ask what someone is like and describe their personality.","intro":{"explanation":"To ask what someone is like, say ¿cómo es? The answer uses ser: es simpático, es divertida. The adjective comes after the verb and changes with the person: -o for a man, -a for a woman. Muy means very. Careful: simpático means friendly, not sympathetic.","examples":[{"target":"¿Cómo es tu hermano? — Es muy simpático.","base":"What is your brother like? — He is very friendly."},{"target":"Mi hermana es divertida.","base":"My sister is funny."}]},"takeaways":["You ask what someone is like with ¿cómo es?","You describe personality with es + adjective, ending in -o or -a."]},{"id":"es-a1-u14-l02","unit_id":"es-a1-u14","position":2,"title_es":"Alto, bajo, delgado","objective_es":"Describe what someone looks like: height, build and age.","intro":{"explanation":"Appearance also goes with ser: es alto (tall), es bajo (short), es delgado (thin), es joven (young). Bajo is only for height; short hair is corto. In conversation you will also hear flaco for thin. Lindo means good-looking, pretty or cute, for people, animals and things; guapo (good-looking) is also common, especially for people. Joven is the same for men and women; the plural is jóvenes. The j in joven sounds like a strong h.","examples":[{"target":"Mi papá es alto y delgado.","base":"My dad is tall and thin."},{"target":"Mis abuelos son bajos.","base":"My grandparents are short."}]},"takeaways":["You describe height and build with alto, bajo and delgado.","You make adjectives plural with -s: altos, bajas, jóvenes."]},{"id":"es-a1-u14-rev1","unit_id":"es-a1-u14","position":3,"title_es":"Review 1","objective_es":"Consolidate “¿Cómo es?” and “Alto, bajo, delgado”.","intro":null,"takeaways":[]},{"id":"es-a1-u14-l03","unit_id":"es-a1-u14","position":4,"title_es":"El pelo y los ojos","objective_es":"Describe someone’s hair and eyes.","intro":{"explanation":"For hair and eyes, Spanish uses tener with the article: tiene el pelo largo (she has long hair), tengo los ojos verdes (I have green eyes). The adjective goes after the noun. Careful: largo means long, not large (large is grande). Rubio is blond and moreno is dark-haired (in some countries moreno also describes dark skin). Listen to the difference: pero (but) has a quick tap like the tt in American butter, perro (dog) has a trilled rr, and pelo (hair) has an l.","examples":[{"target":"Tiene el pelo largo y los ojos verdes.","base":"She has long hair and green eyes."},{"target":"Soy morena, pero mi hermano es rubio.","base":"I have dark hair, but my brother is blond."}]},"takeaways":["You describe hair and eyes with tener: tiene el pelo corto.","You know that largo means long and you can hear pero, perro and pelo."]},{"id":"es-a1-u14-l04","unit_id":"es-a1-u14","position":5,"title_es":"Estoy cansado","objective_es":"Say how you and others feel right now, and choose between ser and estar.","intro":{"explanation":"Ser describes what someone is like (es serio, es divertida). Estar describes how someone is right now, a state that can change: estoy cansado (I’m tired), está contenta (she’s happy). With tú: estás (¿cómo estás?); plural: estamos (we), están (they, ustedes). So Martín es serio means he is a serious person, but hoy está contento means he is happy today.","examples":[{"target":"Hoy estoy muy cansada.","base":"I’m very tired today."},{"target":"Martín es serio, pero hoy está contento.","base":"Martín is a serious person, but today he’s happy."}]},"takeaways":["You say how you feel with estoy: estoy cansado, estoy contenta.","You use ser for what someone is like and estar for how they are now."]},{"id":"es-a1-u14-rev2","unit_id":"es-a1-u14","position":6,"title_es":"Review 2","objective_es":"Consolidate “El pelo y los ojos” and “Estoy cansado”.","intro":null,"takeaways":[]},{"id":"es-a1-u14-l05","unit_id":"es-a1-u14","position":7,"title_es":"¿Cómo es tu familia?","objective_es":"Understand and give short descriptions of people.","intro":{"explanation":"Put it all together: ser for what people are like and what they look like, tener for hair and eyes, and estar for how they feel. Remember that adjectives agree with the person: mi hermana es alta y rubia, mis padres son simpáticos.","examples":[{"target":"Mi hermana es alta y rubia.","base":"My sister is tall and blonde."},{"target":"Mis padres son muy simpáticos.","base":"My parents are very friendly."}]},"takeaways":["You understand a short description of a person in a message.","You describe someone with ser, tener and estar."]},{"id":"es-a1-u14-listen","unit_id":"es-a1-u14","position":8,"title_es":"Listening practice","objective_es":"Recognize the words and phrases of the unit by ear.","intro":null,"takeaways":[]},{"id":"es-a1-u14-words","unit_id":"es-a1-u14","position":9,"title_es":"Words of the unit","objective_es":"Fix the vocabulary of the unit: recognize it and write it.","intro":null,"takeaways":[]},{"id":"es-a1-u14-final","unit_id":"es-a1-u14","position":10,"title_es":"Final review","objective_es":"Show everything from “Describing people”.","intro":null,"takeaways":[]},{"id":"es-a1-u15-l01","unit_id":"es-a1-u15","position":1,"title_es":"Enero, febrero, marzo…","objective_es":"Say the months from January to June and use en + month.","intro":{"explanation":"Spanish months are written with a lowercase letter: enero, febrero, marzo, abril, mayo, junio. To say “in” a month, use en: en marzo. The j in junio sounds like a strong h, and the y in mayo sounds like the y in English yes. The school year doesn’t start in the same month everywhere: in Mexico it starts in agosto, but in Chile and Argentina it starts in marzo, after the southern summer holidays.","examples":[{"target":"En enero no trabajo.","base":"I don’t work in January."},{"target":"Febrero es un mes corto.","base":"February is a short month."}]},"takeaways":["You know the months from enero to junio, written in lowercase.","You say “in” a month with en: en marzo."]},{"id":"es-a1-u15-l02","unit_id":"es-a1-u15","position":2,"title_es":"Julio, agosto…","objective_es":"Say the months from July to December.","intro":{"explanation":"The second half of the year: julio, agosto, septiembre (also written setiembre), octubre, noviembre, diciembre. Junio and julio differ only in n and l, so listen carefully. Seasons depend on the hemisphere: in Mexico and Spain julio is summer and diciembre is winter, but in Chile and Argentina it is the other way round, so Christmas there is hot!","examples":[{"target":"En julio voy a Cusco.","base":"In July I go to Cusco."},{"target":"En diciembre no trabajo.","base":"I don’t work in December."}]},"takeaways":["You know the months from julio to diciembre.","You can hear the difference between junio and julio."]},{"id":"es-a1-u15-rev1","unit_id":"es-a1-u15","position":3,"title_es":"Review 1","objective_es":"Consolidate “Enero, febrero, marzo…” and “Julio, agosto…”.","intro":null,"takeaways":[]},{"id":"es-a1-u15-l03","unit_id":"es-a1-u15","position":4,"title_es":"¿Qué fecha es hoy?","objective_es":"Ask and say the date.","intro":{"explanation":"To ask the date: ¿qué fecha es hoy? Answer with el + number + de + month: hoy es el 9 de julio. Unlike English, the day comes before the month. For the first day of the month say el primero: el primero de mayo (in Spain and some other places people also say el uno de mayo). From the 2nd on, use the normal numbers: el dos, el tres…","examples":[{"target":"¿Qué fecha es hoy? — Es el 20 de junio.","base":"What’s the date today? — It’s June 20."},{"target":"Hoy es el primero de octubre.","base":"Today is October 1."}]},"takeaways":["You ask the date with ¿qué fecha es hoy?","You say a date with el + number + de + month, and el primero for the 1st."]},{"id":"es-a1-u15-l04","unit_id":"es-a1-u15","position":5,"title_es":"El cumpleaños","objective_es":"Talk about birthdays and say when and where you were born.","intro":{"explanation":"To ask a friend about their birthday: ¿cuándo es tu cumpleaños? — Es el 9 de julio (or es en julio). Informally, many people say el cumple. On the day you say ¡feliz cumpleaños! To say when or where you were born: nací el 3 de marzo, nací en Bogotá. For another person (or usted): nació; to ask a friend (tú): ¿cuándo naciste?","examples":[{"target":"¿Cuándo es tu cumpleaños? — Es el 9 de julio.","base":"When is your birthday? — It’s July 9."},{"target":"Nací en Bogotá, en octubre.","base":"I was born in Bogotá, in October."}]},"takeaways":["You ask ¿cuándo es tu cumpleaños? and say ¡feliz cumpleaños!","You say when and where you were born with nací."]},{"id":"es-a1-u15-rev2","unit_id":"es-a1-u15","position":6,"title_es":"Review 2","objective_es":"Consolidate “¿Qué fecha es hoy?” and “El cumpleaños”.","intro":null,"takeaways":[]},{"id":"es-a1-u15-l05","unit_id":"es-a1-u15","position":7,"title_es":"Fechas patrias","objective_es":"Understand dates and birthdays in a conversation and a post.","intro":{"explanation":"Every Spanish-speaking country has its own fechas patrias (national holidays). Independence Day is el 16 de septiembre in Mexico, el 20 de julio in Colombia, el 28 de julio in Peru and el 9 de julio in Argentina. Many countries also have a holiday on el primero de mayo (Labor Day). Remember: dates are el + number + de + month, and months go in lowercase.","examples":[{"target":"El 16 de septiembre es una fecha patria en México.","base":"September 16 is a national holiday in Mexico."},{"target":"El 9 de julio no trabajo.","base":"I don’t work on July 9."}]},"takeaways":["You understand dates and birthdays in a conversation and a post.","You know some national holidays of Spanish-speaking countries."]},{"id":"es-a1-u15-listen","unit_id":"es-a1-u15","position":8,"title_es":"Listening practice","objective_es":"Recognize the words and phrases of the unit by ear.","intro":null,"takeaways":[]},{"id":"es-a1-u15-words","unit_id":"es-a1-u15","position":9,"title_es":"Words of the unit","objective_es":"Fix the vocabulary of the unit: recognize it and write it.","intro":null,"takeaways":[]},{"id":"es-a1-u15-final","unit_id":"es-a1-u15","position":10,"title_es":"Final review","objective_es":"Show everything from “Months and dates”.","intro":null,"takeaways":[]},{"id":"es-a1-u16-l01","unit_id":"es-a1-u16","position":1,"title_es":"¿Qué tiempo hace?","objective_es":"Ask about the weather and say if it is hot, cold or nice.","intro":{"explanation":"For the weather Spanish uses hace: hace calor (it’s hot), hace frío (it’s cold), hace buen tiempo (the weather is nice). To ask: ¿qué tiempo hace? Calor and frío are nouns, so you say hace mucho calor (not muy). In an exclamation like ¡qué calor! the voice starts high and falls. Careful with the vowels: calor (heat) is not color.","examples":[{"target":"¿Qué tiempo hace hoy? — Hace calor.","base":"What’s the weather like today? — It’s hot."},{"target":"¡Qué frío! Hace mucho frío.","base":"So cold! It’s very cold."}]},"takeaways":["You ask ¿qué tiempo hace? and answer with hace calor, hace frío or hace buen tiempo.","You say “very hot” with mucho: hace mucho calor."]},{"id":"es-a1-u16-l02","unit_id":"es-a1-u16","position":2,"title_es":"Llueve, hay sol","objective_es":"Talk about rain, snow, sun and wind.","intro":{"explanation":"Rain and snow have their own verbs: llueve (it’s raining), nieva (it’s snowing). For sun and wind use hay: hay sol, hay viento (you’ll also hear hace sol). La lluvia is the rain. The ll of llueve and lluvia sounds like the y in English yes. Spanish has an even rhythm: every syllable gets about the same time, llue-ve, llu-via.","examples":[{"target":"Hoy llueve mucho.","base":"It’s raining a lot today."},{"target":"Hay sol, pero hace frío.","base":"It’s sunny, but it’s cold."}]},"takeaways":["You say llueve and nieva for rain and snow.","You say hay sol and hay viento for sun and wind."]},{"id":"es-a1-u16-rev1","unit_id":"es-a1-u16","position":3,"title_es":"Review 1","objective_es":"Consolidate “¿Qué tiempo hace?” and “Llueve, hay sol”.","intro":null,"takeaways":[]},{"id":"es-a1-u16-l03","unit_id":"es-a1-u16","position":4,"title_es":"Las estaciones","objective_es":"Name the seasons and say when they are in different countries.","intro":{"explanation":"The seasons take the article: el verano, el otoño, el invierno, la primavera. After en you can drop it: en verano, en invierno. The seasons depend on the hemisphere. In the north (Mexico, Spain, the US) enero is winter and julio is summer. In the south (Chile, Argentina, Uruguay) it is the other way round: enero is summer and julio is winter, so spring starts in septiembre. Near the equator, in Colombia or Ecuador, people talk more about the rainy and the dry season. The ñ in otoño sounds like the ny in canyon.","examples":[{"target":"En enero es verano en Chile.","base":"In January it’s summer in Chile."},{"target":"En invierno hace frío.","base":"It’s cold in winter."}]},"takeaways":["You know the four seasons with their article.","You know that the seasons depend on the hemisphere: enero is summer in Chile and winter in Mexico."]},{"id":"es-a1-u16-l04","unit_id":"es-a1-u16","position":5,"title_es":"Más… que, menos… que","objective_es":"Compare places and say where you prefer to go.","intro":{"explanation":"To compare: más + word + que (more… than) and menos + word + que (less… than): en Bogotá hace más frío que en Cartagena (Bogotá is high in the mountains; Cartagena is on the Caribbean coast). To say two things are equal: tan + adjective + como (as… as). To ask a friend what they prefer: ¿prefieres el mar o la montaña? (preferir changes e to ie: prefiero, prefieres). Listen to the ends of mar (sea), mal (bad) and más (more).","examples":[{"target":"En Bogotá hace más frío que en Cartagena.","base":"It’s colder in Bogotá than in Cartagena."},{"target":"La playa es tan linda como la montaña.","base":"The beach is as nice as the mountains."}]},"takeaways":["You compare with más… que, menos… que and tan… como.","You talk about the sea, the beach and the mountains."]},{"id":"es-a1-u16-rev2","unit_id":"es-a1-u16","position":6,"title_es":"Review 2","objective_es":"Consolidate “Las estaciones” and “Más… que, menos… que”.","intro":null,"takeaways":[]},{"id":"es-a1-u16-l05","unit_id":"es-a1-u16","position":7,"title_es":"¿Cómo está el clima?","objective_es":"Understand the weather in a phone call and a postcard.","intro":{"explanation":"In much of Latin America you’ll also hear ¿cómo está el clima? for “what’s the weather like?” (strictly, el clima is the climate and el tiempo the weather). Put it together: hace calor or frío, llueve, nieva, hay sol, and compare places with más… que. Remember: when it is summer in Mexico or Spain, it is winter in Chile and Argentina.","examples":[{"target":"En Cartagena hace calor y hay sol.","base":"In Cartagena it’s hot and sunny."},{"target":"En Bariloche nieva más que en Santiago.","base":"It snows more in Bariloche than in Santiago."}]},"takeaways":["You understand the weather in a conversation and a postcard.","You describe the day and compare two places."]},{"id":"es-a1-u16-listen","unit_id":"es-a1-u16","position":8,"title_es":"Listening practice","objective_es":"Recognize the words and phrases of the unit by ear.","intro":null,"takeaways":[]},{"id":"es-a1-u16-words","unit_id":"es-a1-u16","position":9,"title_es":"Words of the unit","objective_es":"Fix the vocabulary of the unit: recognize it and write it.","intro":null,"takeaways":[]},{"id":"es-a1-u16-final","unit_id":"es-a1-u16","position":10,"title_es":"Final review","objective_es":"Show everything from “Weather and seasons”.","intro":null,"takeaways":[]},{"id":"es-a1-u17-l01","unit_id":"es-a1-u17","position":1,"title_es":"En autobús, en metro","objective_es":"Say how you get around: by bus, train, car, bike or on foot.","intro":{"explanation":"To say how you travel, use en + vehicle with no article: en autobús (by bus), en metro (by subway), en tren, en carro, en bicicleta (or en bici). The exception is a pie (on foot). Some of these words change from country to country: in Mexico the city bus is also el camión, in Argentina el colectivo; for car you will also hear el auto (Chile, Argentina) and el coche (Spain). B and v sound exactly the same: bicicleta, voy, autobús.","examples":[{"target":"Voy a la facultad en autobús.","base":"I go to college by bus."},{"target":"Mi hermana va al trabajo a pie.","base":"My sister walks to work."}]},"takeaways":["You say how you travel with en + vehicle: en autobús, en metro.","You say on foot with a pie."]},{"id":"es-a1-u17-l02","unit_id":"es-a1-u17","position":2,"title_es":"Tomar el autobús","objective_es":"Say which transport you take, and talk about tickets and planes.","intro":{"explanation":"With transport, use tomar: tomo el autobús (I take the bus), tomas el metro (you take, tú), toma el tren (he, she or usted takes). In Spain people say coger, but in much of Latin America that verb is vulgar, so always say tomar. For a plane or a long-distance bus you need a pasaje (ticket; in Mexico people say el boleto, in Spain el billete). Ahora means now; the h is silent.","examples":[{"target":"Ahora tomo el metro.","base":"Now I’m taking the subway."},{"target":"¿Tomas el autobús? — No, voy a pie.","base":"Do you take the bus? — No, I walk."}]},"takeaways":["You say tomar for transport: tomo el autobús, tomas el metro.","You know el avión, el pasaje and ahora."]},{"id":"es-a1-u17-rev1","unit_id":"es-a1-u17","position":3,"title_es":"Review 1","objective_es":"Consolidate “En autobús, en metro” and “Tomar el autobús”.","intro":null,"takeaways":[]},{"id":"es-a1-u17-l03","unit_id":"es-a1-u17","position":4,"title_es":"Voy a viajar","objective_es":"Talk about plans with ir a + infinitive.","intro":{"explanation":"For plans, use ir a + infinitive, just like English “going to”: voy a viajar (I’m going to travel), vas a visitar (you’re going to visit), vamos a tomar el tren. Only ir changes: voy, vas, va, vamos, van + a + the verb as it is. To visit a person, add a: voy a visitar a mi abuela. Viaje, visitar and vacaciones start with v, but it sounds just like a b.","examples":[{"target":"Voy a viajar en avión.","base":"I’m going to travel by plane."},{"target":"Vamos a visitar a mis abuelos.","base":"We’re going to visit my grandparents."}]},"takeaways":["You talk about plans with voy a, vas a, vamos a + verb.","You talk about trips and holidays: el viaje, las vacaciones."]},{"id":"es-a1-u17-l04","unit_id":"es-a1-u17","position":5,"title_es":"Este fin de semana","objective_es":"Say when your plans are and whether you are staying or going.","intro":{"explanation":"Time words for plans: esta noche (tonight), este fin de semana (this weekend), la semana que viene (next week) and mañana. Quedarse means to stay, and it comes with a small word that changes with the person: me quedo (I stay), te quedas (you stay, tú), se queda (he, she or usted stays). Me quedo en casa = I’m staying home.","examples":[{"target":"Esta noche me quedo en casa.","base":"Tonight I’m staying home."},{"target":"La semana que viene voy a visitar a mi abuela.","base":"Next week I’m going to visit my grandmother."}]},"takeaways":["You say when with esta noche, este fin de semana and la semana que viene.","You say you are staying with me quedo, te quedas, se queda."]},{"id":"es-a1-u17-rev2","unit_id":"es-a1-u17","position":6,"title_es":"Review 2","objective_es":"Consolidate “Voy a viajar” and “Este fin de semana”.","intro":null,"takeaways":[]},{"id":"es-a1-u17-l05","unit_id":"es-a1-u17","position":7,"title_es":"Planes de viaje","objective_es":"Understand plans and trips in a conversation and a message.","intro":{"explanation":"Put it together: how you travel (en tren, a pie), what you are going to do (voy a + verb) and when (esta noche, la semana que viene). In much of Latin America, long trips between cities are often by long-distance bus; big cities such as Mexico City, Santiago or Buenos Aires also have a metro.","examples":[{"target":"La semana que viene voy a viajar en avión.","base":"Next week I’m going to travel by plane."},{"target":"Ahora tomo el metro y después voy a pie.","base":"Now I’m taking the subway and then I’ll walk."}]},"takeaways":["You understand someone’s plans in a conversation and a message.","You say what you are going to do, when and how you will travel."]},{"id":"es-a1-u17-listen","unit_id":"es-a1-u17","position":8,"title_es":"Listening practice","objective_es":"Recognize the words and phrases of the unit by ear.","intro":null,"takeaways":[]},{"id":"es-a1-u17-words","unit_id":"es-a1-u17","position":9,"title_es":"Words of the unit","objective_es":"Fix the vocabulary of the unit: recognize it and write it.","intro":null,"takeaways":[]},{"id":"es-a1-u17-final","unit_id":"es-a1-u17","position":10,"title_es":"Final review","objective_es":"Show everything from “Transport and plans”.","intro":null,"takeaways":[]},{"id":"es-a2-u01-l01","unit_id":"es-a2-u01","position":1,"title_es":"Ayer, anoche, el finde pasado","objective_es":"Say what you did yesterday with regular -ar verbs.","intro":{"explanation":"For a finished action in the past, -ar verbs take -é in the yo form, with the stress on the last syllable: hablar → hablé, mirar → miré, tomar → tomé, terminar → terminé. Useful time words: ayer (yesterday), anoche (last night) and el fin de semana pasado (last weekend, or el finde pasado). Listen to the stress: hablo (I speak) is stressed on the first syllable; hablé (I spoke) and habló (he spoke) on the last one.","examples":[{"target":"Ayer hablé con mi mamá.","base":"Yesterday I talked to my mom."},{"target":"Anoche miré fútbol.","base":"Last night I watched football."}]},"takeaways":["You form the past of -ar verbs with -é: hablé, miré, tomé, terminé.","You place actions in the past with ayer, anoche and el fin de semana pasado."]},{"id":"es-a2-u01-l02","unit_id":"es-a2-u01","position":2,"title_es":"Comí, dormí, leí","objective_es":"Talk about the past with -er and -ir verbs and ask a friend with tú.","intro":{"explanation":"With -er and -ir verbs, yo ends in -í: comer → comí, dormir → dormí, leer → leí. To ask a friend (tú), add -aste to -ar verbs and -iste to -er and -ir verbs: ¿hablaste?, ¿comiste?, ¿dormiste? Careful: in the present the tú form ends in -s (hablas, comes), but in the past it does not (you may hear comistes, but it is not standard). For él, ella and usted: habló, comió, and dormir changes its vowel: durmió.","examples":[{"target":"¿Qué comiste ayer? — Comí pescado.","base":"What did you eat yesterday? — I ate fish."},{"target":"¿Dormiste bien? — Sí, dormí mucho.","base":"Did you sleep well? — Yes, I slept a lot."}]},"takeaways":["You say comí, dormí, leí and ask ¿comiste?, ¿dormiste?","You use habló, comió for él, ella and usted."]},{"id":"es-a2-u01-rev1","unit_id":"es-a2-u01","position":3,"title_es":"Review 1","objective_es":"Consolidate “Ayer, anoche, el finde pasado” and “Comí, dormí, leí”.","intro":null,"takeaways":[]},{"id":"es-a2-u01-l03","unit_id":"es-a2-u01","position":4,"title_es":"Hice, fui, vi","objective_es":"Use the irregular pasts of hacer, ir, ser and ver.","intro":{"explanation":"Some of the most common verbs are irregular in the past and have no written accent. Hacer (to do, to make): hice, hiciste, hizo. Ir (to go): fui, fuiste, fue; ser (to be) has exactly the same forms, so fue muy lindo means it was really nice. Ver (to see): vi, viste, vio. The classic Monday question is ¿Qué hiciste el finde? Notice the double negative: no hice nada (I didn’t do anything).","examples":[{"target":"¿Qué hiciste el finde? — Fui al cine.","base":"What did you do at the weekend? — I went to the cinema."},{"target":"Vi una película muy divertida.","base":"I saw a really funny film."}]},"takeaways":["You use hice, fui and vi, and ask ¿qué hiciste?, ¿fuiste?, ¿viste?","You say no hice nada with two negatives."]},{"id":"es-a2-u01-l04","unit_id":"es-a2-u01","position":5,"title_es":"¿Ya limpiaste?","objective_es":"Talk about housework and say what you have already done or not done yet.","intro":{"explanation":"Ya + past means already: ya limpié (I’ve already cleaned). Todavía no + past means not yet: todavía no terminé. Where English uses the present perfect (Have you cleaned yet?), Latin Americans use the simple past: ¿Ya limpiaste? (In Spain you will often hear ¿Ya has limpiado?) Housework: limpiar (to clean), ordenar (to tidy up) and hacer las compras (to do the food shopping; in the past, hice las compras). After quiero, odio or voy a, the verb stays in the infinitive: quiero ordenar.","examples":[{"target":"¿Ya limpiaste la cocina? — Sí, ya limpié.","base":"Have you cleaned the kitchen yet? — Yes, I already did."},{"target":"¿Ya hiciste las compras? — No, todavía no.","base":"Have you done the shopping yet? — No, not yet."}]},"takeaways":["You say ya for already and todavía no for not yet, with the simple past.","You talk about housework with limpiar, ordenar and hacer las compras."]},{"id":"es-a2-u01-rev2","unit_id":"es-a2-u01","position":6,"title_es":"Review 2","objective_es":"Consolidate “Hice, fui, vi” and “¿Ya limpiaste?”.","intro":null,"takeaways":[]},{"id":"es-a2-u01-l05","unit_id":"es-a2-u01","position":7,"title_es":"¿Qué hiciste el finde?","objective_es":"Understand people telling you about their weekend and tell them about yours.","intro":{"explanation":"On Monday, everyone asks ¿Qué hiciste el fin de semana? (or, informally, ¿Qué hiciste el finde?, a short form heard in many countries). In much of Latin America, Sunday means a long lunch with the family (in Argentina and Uruguay, often an asado, a barbecue) and football in the afternoon. To tell a story, list the days and join the actions with y and después. To sum it up: fue muy lindo (it was really nice).","examples":[{"target":"El sábado fui al cine y el domingo comí un asado.","base":"On Saturday I went to the cinema and on Sunday I had an asado."},{"target":"Fue muy lindo.","base":"It was really nice."}]},"takeaways":["You understand a story about the weekend told in the simple past.","You tell what you did on different days with the simple past."]},{"id":"es-a2-u01-listen","unit_id":"es-a2-u01","position":8,"title_es":"Listening practice","objective_es":"Recognize the words and phrases of the unit by ear.","intro":null,"takeaways":[]},{"id":"es-a2-u01-words","unit_id":"es-a2-u01","position":9,"title_es":"Words of the unit","objective_es":"Fix the vocabulary of the unit: recognize it and write it.","intro":null,"takeaways":[]},{"id":"es-a2-u01-final","unit_id":"es-a2-u01","position":10,"title_es":"Final review","objective_es":"Show everything from “What did you do on the weekend?”.","intro":null,"takeaways":[]},{"id":"es-a2-u02-l01","unit_id":"es-a2-u02","position":1,"title_es":"Estuve, tuve","objective_es":"Say where you were and what you had, using the past of estar and tener.","intro":{"explanation":"Estar and tener have irregular pasts with a u in the stem and no written accent: estar → estuve, estuviste, estuvo; tener → tuve, tuviste, tuvo. Use estuve to say where you were for a while: estuve en Lima. To say what something was like, fue (from ser) is the usual choice: la estadía fue muy linda. La estadía (the stay) is the usual word in Latin America; in Spain you will hear la estancia. El extranjero means abroad: viajar al extranjero, estuve en el extranjero.","examples":[{"target":"Estuve una semana en Lima.","base":"I was in Lima for a week."},{"target":"La estadía en el hotel fue muy linda.","base":"The stay at the hotel was really nice."}]},"takeaways":["You say where you were with estuve and what you had with tuve.","You ask a friend ¿estuviste…? and ¿tuviste…?"]},{"id":"es-a2-u02-l02","unit_id":"es-a2-u02","position":2,"title_es":"Salí, llegué, volví","objective_es":"Say when you left, arrived and came back, and whether you were late or on time.","intro":{"explanation":"Salir and volver are regular: salí, saliste, salió; volví, volviste, volvió. Llegar is regular too, but its yo form is spelled llegué: the u is silent and keeps the g hard, like the g in get. Without it, ge would sound like the strong h of the j in viaje. Salir de, llegar a: salí de Lima, llegué a Cusco (de + el = del, a + el = al). Llegar tarde means to arrive late; llegar a tiempo, on time.","examples":[{"target":"Salí del hotel a las seis.","base":"I left the hotel at six."},{"target":"El vuelo llegó a tiempo.","base":"The flight arrived on time."}]},"takeaways":["You say salí, llegué and volví, and write llegué with gu.","You say whether something arrived tarde or a tiempo."]},{"id":"es-a2-u02-rev1","unit_id":"es-a2-u02","position":3,"title_es":"Review 1","objective_es":"Consolidate “Estuve, tuve” and “Salí, llegué, volví”.","intro":null,"takeaways":[]},{"id":"es-a2-u02-l03","unit_id":"es-a2-u02","position":4,"title_es":"Vine hace dos años","objective_es":"Say how long ago something happened and talk about luggage and documents.","intro":{"explanation":"Venir is irregular: vine, viniste, vino (careful: vino is also wine!). Quedarse (to stay) is regular and keeps its pronoun: me quedé, te quedaste, se quedó. To say how long ago, put hace before the time: hace dos años (two years ago), hace tres días, hace una semana. A suitcase is la maleta (in Argentina and Uruguay you will also hear la valija).","examples":[{"target":"Vine a Bogotá hace dos años.","base":"I came to Bogotá two years ago."},{"target":"Me quedé una semana en Cusco.","base":"I stayed in Cusco for a week."}]},"takeaways":["You say how long ago something happened with hace + time.","You use vine and me quedé to talk about a trip."]},{"id":"es-a2-u02-l04","unit_id":"es-a2-u02","position":5,"title_es":"Mi primer viaje al extranjero","objective_es":"Understand a postcard about a trip and talk about problems on a journey.","intro":{"explanation":"In a postcard or a message about a trip, you say when you arrived, where you stayed and what happened: llegué el lunes, me quedé en un hotel, tuve un problema. Querida or querido (dear) opens a note to someone close, and un beso (a kiss) is the usual way to sign off. Pronunciation: the j, and the g before e or i, sound like a strong h (viaje, Argentina), but gue in llegué is a hard g.","examples":[{"target":"Llegué a Madrid el lunes.","base":"I arrived in Madrid on Monday."},{"target":"Tuve un problema con mi maleta.","base":"I had a problem with my suitcase."}]},"takeaways":["You understand a postcard about arrivals, hotels and problems.","You use llegó, salió and tuve to say what happened on a journey."]},{"id":"es-a2-u02-rev2","unit_id":"es-a2-u02","position":6,"title_es":"Review 2","objective_es":"Consolidate “Vine hace dos años” and “Mi primer viaje al extranjero”.","intro":null,"takeaways":[]},{"id":"es-a2-u02-l05","unit_id":"es-a2-u02","position":7,"title_es":"¿Cómo fue el viaje?","objective_es":"Understand a friend telling you about a trip and tell the story of your own.","intro":{"explanation":"To ask a friend about a trip: ¿Cómo fue el viaje?, ¿Dónde estuviste?, ¿Cuánto tiempo te quedaste? For a group, use the nosotros forms; for -ar and -ir verbs they look like the present (salimos, nos quedamos), and the time words tell you it is the past. Seasons depend on the hemisphere: July is summer in Mexico and Spain, but winter in Chile and Argentina, where Bariloche, in Patagonia, is famous for its lakes, mountains and snow.","examples":[{"target":"¿Cómo fue el viaje? — Muy lindo.","base":"How was the trip? — Really nice."},{"target":"Salimos el sábado y volvimos anoche.","base":"We left on Saturday and came back last night."}]},"takeaways":["You follow a conversation about a trip told in the past.","You tell a trip in order: when you left, where you stayed and when you came back."]},{"id":"es-a2-u02-listen","unit_id":"es-a2-u02","position":8,"title_es":"Listening practice","objective_es":"Recognize the words and phrases of the unit by ear.","intro":null,"takeaways":[]},{"id":"es-a2-u02-words","unit_id":"es-a2-u02","position":9,"title_es":"Words of the unit","objective_es":"Fix the vocabulary of the unit: recognize it and write it.","intro":null,"takeaways":[]},{"id":"es-a2-u02-final","unit_id":"es-a2-u02","position":10,"title_es":"Final review","objective_es":"Show everything from “Travel”.","intro":null,"takeaways":[]},{"id":"es-a2-u03-l01","unit_id":"es-a2-u03","position":1,"title_es":"Me gustaría…, ¿podría…?","objective_es":"Make polite requests in a restaurant or a hotel.","intro":{"explanation":"Three polite ways to ask for something: me gustaría + infinitive or noun (I would like): me gustaría reservar una mesa; ¿podría + infinitive? (could you…?, with usted): ¿podría traer agua?; and ¿me trae…? (could you bring me…?), the everyday way to order: ¿me trae un café? Me gusta is I like in general; me gustaría is a request. Reservar is to book. Say requests softly, with the voice rising at the end; the single r in podría and traer is a quick tap, like the tt in American butter.","examples":[{"target":"Me gustaría reservar una mesa para dos.","base":"I would like to book a table for two."},{"target":"¿Me trae la cuenta, por favor?","base":"Could you bring me the bill, please?"}]},"takeaways":["You ask politely with me gustaría, ¿podría…? and ¿me trae…?","You book a table with reservar and ask for la cuenta."]},{"id":"es-a2-u03-l02","unit_id":"es-a2-u03","position":2,"title_es":"Una habitación doble","objective_es":"Book a hotel room and ask about the price, what is included and the floor.","intro":{"explanation":"At a hotel you ask for una habitación doble (a double room). Prices are given por noche (per night). Incluido agrees like any adjective: el desayuno está incluido, la bebida está incluida. Floors are pisos: el primer piso, el tercer piso; the ground floor is la planta baja. El ascensor is the elevator. Habitación has a silent h, and the stress falls on the last syllable: -ción.","examples":[{"target":"Quisiera una habitación doble, por favor.","base":"I’d like a double room, please."},{"target":"El desayuno está incluido.","base":"Breakfast is included."}]},"takeaways":["You book a room and ask about the price por noche.","You ask whether something is incluido and on which piso the room is."]},{"id":"es-a2-u03-rev1","unit_id":"es-a2-u03","position":3,"title_es":"Review 1","objective_es":"Consolidate “Me gustaría…, ¿podría…?” and “Una habitación doble”.","intro":null,"takeaways":[]},{"id":"es-a2-u03-l03","unit_id":"es-a2-u03","position":4,"title_es":"La carta y el menú del día","objective_es":"Understand the menu and order a starter, a main course and a dessert.","intro":{"explanation":"La carta is the full menu. El menú del día is a set menu at a fixed price, very common at lunchtime: una entrada (a starter; careful, entrada also means entrance or ticket), un plato principal and un postre. To order each course: de entrada…, de plato principal…, de postre… Classics across Latin America: empanadas as a starter and flan for dessert (in Argentina and Uruguay, flan con dulce de leche). Note the written accent of menú: the stress falls on the last syllable.","examples":[{"target":"De entrada, una empanada.","base":"As a starter, an empanada."},{"target":"De postre, un flan con dulce de leche.","base":"For dessert, a flan with dulce de leche."}]},"takeaways":["You tell la carta from el menú del día.","You order each course with de entrada, de plato principal and de postre."]},{"id":"es-a2-u03-l04","unit_id":"es-a2-u03","position":5,"title_es":"Término medio o bien cocido","objective_es":"Say how you want your meat and understand what is included and the tip.","intro":{"explanation":"When you order meat, the waiter asks how you want it: término medio (medium, pink inside) or bien cocido (well done); for rare, say poco cocido. Cocido agrees with the noun: el bistec bien cocido, la carne bien cocida, but término medio never changes. In Spain and Argentina you will also hear a punto for medium. La propina (the tip) is often not included in la cuenta; around 10 % is usual in much of Latin America (in Mexico, 10 to 15 %).","examples":[{"target":"El bistec término medio, por favor.","base":"The steak medium, please."},{"target":"La propina no está incluida.","base":"The tip isn’t included."}]},"takeaways":["You order your meat término medio or bien cocido.","You know that la propina is not usually included."]},{"id":"es-a2-u03-rev2","unit_id":"es-a2-u03","position":6,"title_es":"Review 2","objective_es":"Consolidate “La carta y el menú del día” and “Término medio o bien cocido”.","intro":null,"takeaways":[]},{"id":"es-a2-u03-l05","unit_id":"es-a2-u03","position":7,"title_es":"En el restaurante","objective_es":"Follow a conversation with a waiter and order a whole meal.","intro":{"explanation":"Dinner times vary: in Mexico City or Bogotá many people have dinner around eight, while in Buenos Aires or Madrid restaurants fill up after nine or ten. The waiter is el mesero or la mesera (in Spain, el camarero); to call them, make eye contact, raise your hand or say disculpe. A typical order: a steak (un bistec) with fries (papas fritas), a drink (agua con gas or sin gas, or wine) and a dessert. Finish with ¿podría traerme la cuenta?, said softly and rising at the end.","examples":[{"target":"¿Me trae un agua sin gas?","base":"Could you bring me a still water?"},{"target":"¿Podría traerme la cuenta?","base":"Could you bring me the bill?"}]},"takeaways":["You follow a waiter’s questions and answer them politely.","You order a full meal and ask for the bill."]},{"id":"es-a2-u03-listen","unit_id":"es-a2-u03","position":8,"title_es":"Listening practice","objective_es":"Recognize the words and phrases of the unit by ear.","intro":null,"takeaways":[]},{"id":"es-a2-u03-words","unit_id":"es-a2-u03","position":9,"title_es":"Words of the unit","objective_es":"Fix the vocabulary of the unit: recognize it and write it.","intro":null,"takeaways":[]},{"id":"es-a2-u03-final","unit_id":"es-a2-u03","position":10,"title_es":"Final review","objective_es":"Show everything from “Restaurant and hotel”.","intro":null,"takeaways":[]},{"id":"es-a2-u04-l01","unit_id":"es-a2-u04","position":1,"title_es":"Cuando era niño…","objective_es":"Say where you lived and what you were like as a child.","intro":{"explanation":"To talk about your childhood, start with cuando era niño (a girl says cuando era niña) or the shorter de niño / de niña (in Argentina you will also hear de chico, and in Spain de pequeño). Then use the imperfect: era (I was), vivía (I used to live). Vivir → vivía: the í has an accent, so the i and the a are two separate syllables: vi-ví-a. The same form works for he and she: Lucía vivía en Lima. To ask a friend, add -s: ¿Dónde vivías?","examples":[{"target":"Cuando era niño, vivía en un pueblo.","base":"When I was little, I lived in a village."},{"target":"De niña, era muy tímida.","base":"As a girl, I was very shy."}]},"takeaways":["You start a childhood memory with cuando era niño or de niño.","You say where you lived with vivía and what you were like with era."]},{"id":"es-a2-u04-l02","unit_id":"es-a2-u04","position":2,"title_es":"Tenía, había, jugaba","objective_es":"Talk about what you had, what there was and what you played as a child.","intro":{"explanation":"Verbs in -ar take -aba: jugar → jugaba (I used to play). Verbs in -er take -ía: tener → tenía (I used to have). Había is the past of hay: there was or there were, always the same form (había un cine, había dos escuelas). You play a sport with jugar a: jugaba al fútbol (in Mexico you will also hear jugaba fútbol). La primaria is primary school, and in jugaba the b between vowels is soft, almost like a v.","examples":[{"target":"En mi pueblo había un cine.","base":"There was a cinema in my village."},{"target":"De niño, tenía un perro y jugaba con él.","base":"As a kid, I had a dog and I used to play with it."}]},"takeaways":["You say what you had with tenía and what there was with había.","You say what you used to play with jugaba."]},{"id":"es-a2-u04-rev1","unit_id":"es-a2-u04","position":3,"title_es":"Review 1","objective_es":"Consolidate “Cuando era niño…” and “Tenía, había, jugaba”.","intro":null,"takeaways":[]},{"id":"es-a2-u04-l03","unit_id":"es-a2-u04","position":4,"title_es":"Generalmente, cada verano","objective_es":"Describe habits and routines in the past.","intro":{"explanation":"The imperfect is also for things you did again and again: generalmente (usually), siempre, a veces, todos los días, cada verano (every summer). Cada never changes and goes with a singular noun: cada verano, cada domingo. Two useful irregular verbs: ir → iba (I used to go), ver → veía (I used to see). For we: íbamos, with an accent on the first í.","examples":[{"target":"Cada verano íbamos a la playa.","base":"Every summer we went to the beach."},{"target":"Generalmente veía a mis abuelos los domingos.","base":"I usually saw my grandparents on Sundays."}]},"takeaways":["You describe past habits with generalmente, siempre or cada + the imperfect.","You use iba and veía, the imperfect of ir and ver."]},{"id":"es-a2-u04-l04","unit_id":"es-a2-u04","position":5,"title_es":"Antes y ahora","objective_es":"Compare the past with the present and talk about growing up.","intro":{"explanation":"Antes (before, in the past) goes with the imperfect; ahora (now) goes with the present: antes vivía en el campo; ahora vivo en la ciudad. To say where you grew up, use the preterite of crecer: crecí en Cusco (the whole period, seen as finished). Careful: un recuerdo is a memory (or a souvenir), and recordar means to remember, not to record.","examples":[{"target":"Antes vivía en el campo; ahora vivo en la ciudad.","base":"I used to live in the countryside; now I live in the city."},{"target":"Crecí en un pueblo chico.","base":"I grew up in a small village."}]},"takeaways":["You contrast antes + imperfect with ahora + present.","You say where you grew up with crecí en."]},{"id":"es-a2-u04-rev2","unit_id":"es-a2-u04","position":6,"title_es":"Review 2","objective_es":"Consolidate “Generalmente, cada verano” and “Antes y ahora”.","intro":null,"takeaways":[]},{"id":"es-a2-u04-l05","unit_id":"es-a2-u04","position":7,"title_es":"Mis recuerdos","objective_es":"Understand and tell short memories of your childhood.","intro":{"explanation":"A childhood memory usually mixes the imperfect for the scene and the habits (vivía, había, jugábamos) with a time expression (cuando era niña, cada verano). Listen to the stress: había, tenía and vivía have three syllables because the accent on í separates it from the a (ha-bí-a), while in familia the i and the a are said together. With ellos the imperfect ends in -aban or -ían: mis abuelos vivían en el campo.","examples":[{"target":"Cuando era niña, había un cine cerca de mi casa.","base":"When I was little, there was a cinema near my house."},{"target":"Mis abuelos vivían en el campo.","base":"My grandparents lived in the countryside."}]},"takeaways":["You understand a short story about someone’s childhood.","You tell a memory with cuando era niño and the imperfect."]},{"id":"es-a2-u04-listen","unit_id":"es-a2-u04","position":8,"title_es":"Listening practice","objective_es":"Recognize the words and phrases of the unit by ear.","intro":null,"takeaways":[]},{"id":"es-a2-u04-words","unit_id":"es-a2-u04","position":9,"title_es":"Words of the unit","objective_es":"Fix the vocabulary of the unit: recognize it and write it.","intro":null,"takeaways":[]},{"id":"es-a2-u04-final","unit_id":"es-a2-u04","position":10,"title_es":"Final review","objective_es":"Show everything from “When I was a kid”.","intro":null,"takeaways":[]},{"id":"es-a2-u05-l01","unit_id":"es-a2-u05","position":1,"title_es":"¿Qué pasó?","objective_es":"Ask what happened and say that something was stolen.","intro":{"explanation":"¿Qué pasó? means what happened? In the preterite, -ar verbs end in -é for yo (llamé, llegué) and in -ó for él / ella (pasó, robó, llegó). Alguien is someone. When you don’t know who did it, you can also say me robaron (they stole from me). Your wallet is la billetera (in some countries also la cartera, which in others means a handbag). Notice: me robó la billetera, not mi billetera.","examples":[{"target":"¿Qué pasó? — Alguien me robó la billetera.","base":"What happened? — Someone stole my wallet."},{"target":"Llamé a la policía.","base":"I called the police."}]},"takeaways":["You ask ¿qué pasó? and answer with the preterite (pasó, robó).","You say what was stolen with alguien me robó… or me robaron…"]},{"id":"es-a2-u05-l02","unit_id":"es-a2-u05","position":2,"title_es":"Mientras estaba…","objective_es":"Describe the scene: the weather and what was going on.","intro":{"explanation":"The background of a story goes in the imperfect: llovía (it was raining), había poca luz. For an action in progress use estaba + gerund: estaba caminando, estaba comiendo. The gerund ends in -ando (-ar verbs) or -iendo (-er and -ir verbs), and the stress always falls on an or ien: ca-mi-nan-do, co-mien-do (ie is one syllable). Mientras means while. In llovía, the ll sounds like the y in yes.","examples":[{"target":"Llovía y yo estaba caminando por la calle.","base":"It was raining and I was walking down the street."},{"target":"Mientras estaba comiendo, llegó mi hermano.","base":"While I was eating, my brother arrived."}]},"takeaways":["You describe the scene with the imperfect: llovía, había, estaba.","You say what was going on with estaba + -ando / -iendo."]},{"id":"es-a2-u05-rev1","unit_id":"es-a2-u05","position":3,"title_es":"Review 1","objective_es":"Consolidate “¿Qué pasó?” and “Mientras estaba…”.","intro":null,"takeaways":[]},{"id":"es-a2-u05-l03","unit_id":"es-a2-u05","position":4,"title_es":"De repente…","objective_es":"Tell the events of a story with de repente, entonces, por suerte and lamentablemente.","intro":{"explanation":"After the scene comes the event: de repente (suddenly) + preterite. Entonces (then, so) introduces the next step, and the story ends with por suerte (luckily) or lamentablemente (unfortunately). In accidente the first c sounds like k and the second like s (seseo): ak-si-den-te. Fue (it was) is the preterite of ser, for one finished event: fue un accidente.","examples":[{"target":"Estaba en la calle y, de repente, vi un accidente.","base":"I was in the street and suddenly I saw an accident."},{"target":"Por suerte, la policía llegó a tiempo.","base":"Luckily, the police arrived on time."}]},"takeaways":["You introduce the event with de repente and the next step with entonces.","You end a story with por suerte or lamentablemente."]},{"id":"es-a2-u05-l04","unit_id":"es-a2-u05","position":5,"title_es":"Tuve miedo","objective_es":"Say how you felt and what you lost.","intro":{"explanation":"To be scared is tener miedo, literally to have fear (like tener frío or tener calor). In a story: tenía miedo describes how you felt, tuve miedo is the moment you got scared. Miedo is a noun, so you say mucho miedo, not muy miedo. Perder means to lose (perdí la billetera) and also to miss a train or a bus (perdí el autobús). Your neighbor is el vecino or la vecina.","examples":[{"target":"Perdí la billetera en el autobús.","base":"I lost my wallet on the bus."},{"target":"Tuve mucho miedo.","base":"I was very scared."}]},"takeaways":["You say you were scared with tuve miedo or tenía miedo.","You say what you lost or missed with perdí."]},{"id":"es-a2-u05-rev2","unit_id":"es-a2-u05","position":6,"title_es":"Review 2","objective_es":"Consolidate “De repente…” and “Tuve miedo”.","intro":null,"takeaways":[]},{"id":"es-a2-u05-l05","unit_id":"es-a2-u05","position":7,"title_es":"Acabo de llegar","objective_es":"Say what you have just done and understand a complete short story.","intro":{"explanation":"Acabar de + infinitive means to have just done something: acabo de llegar (I’ve just arrived). Only acabar changes: tú acabas de comer, ella acaba de salir, ustedes acaban de llegar. In Latin America this is the usual way to say I’ve just…; the present perfect (he llegado) is less common there than in Spain. A story has a rhythm: the scene in the imperfect (estaba, llovía), the event with de repente + preterite, the next step with entonces, and the end with por suerte or lamentablemente.","examples":[{"target":"Acabo de llegar a casa.","base":"I’ve just got home."},{"target":"Mi hermana acaba de salir.","base":"My sister has just gone out."}]},"takeaways":["You say what you have just done with acabo de + infinitive.","You understand a story told with the imperfect, the preterite and connectors."]},{"id":"es-a2-u05-listen","unit_id":"es-a2-u05","position":8,"title_es":"Listening practice","objective_es":"Recognize the words and phrases of the unit by ear.","intro":null,"takeaways":[]},{"id":"es-a2-u05-words","unit_id":"es-a2-u05","position":9,"title_es":"Words of the unit","objective_es":"Fix the vocabulary of the unit: recognize it and write it.","intro":null,"takeaways":[]},{"id":"es-a2-u05-final","unit_id":"es-a2-u05","position":10,"title_es":"Final review","objective_es":"Show everything from “What happened?”.","intro":null,"takeaways":[]},{"id":"es-a2-u06-l01","unit_id":"es-a2-u06","position":1,"title_es":"¿Quieres venir?","objective_es":"Invite a friend and accept an invitation.","intro":{"explanation":"To invite a friend: ¿quieres venir a…? Querer changes its e to ie: quiero, quieres, quiere. With usted: ¿quiere venir?; with a group: ¿quieren venir? You can also say te invito a…, which often means you are paying. To accept: ¡claro! (sure, of course) or sí, con gusto (yes, with pleasure). In Argentina and Uruguay you will hear dale, and in Spain vale. Careful: mucho gusto is only for meeting someone. In ¿quieres venir? your voice goes up at the end, as in a yes / no question in English.","examples":[{"target":"¿Quieres venir a mi fiesta? — ¡Claro!","base":"Do you want to come to my party? — Sure!"},{"target":"Te invito a cenar el sábado. — Sí, con gusto.","base":"Let me take you out to dinner on Saturday. — Yes, with pleasure."}]},"takeaways":["You invite a friend with ¿quieres venir…? or te invito a…","You accept with claro or con gusto."]},{"id":"es-a2-u06-l02","unit_id":"es-a2-u06","position":2,"title_es":"Lo siento, no puedo","objective_es":"Decline politely, give a reason and say when you are free.","intro":{"explanation":"To say no politely, start with lo siento (I’m sorry), then no puedo (I can’t) and a reason with tengo que + infinitive (I have to): lo siento, no puedo, tengo que trabajar. With tú: ¿puedes? (can you?); poder changes o to ue, as in puedo. To say you are available: estoy libre (libre is the same for a man or a woman). In most Spanish-speaking countries a flat no sounds rude: people give a reason and suggest another plan (el plan).","examples":[{"target":"Lo siento, no puedo. Tengo que trabajar.","base":"I’m sorry, I can’t. I have to work."},{"target":"¿Estás libre el domingo? — Sí, estoy libre.","base":"Are you free on Sunday? — Yes, I’m free."}]},"takeaways":["You decline with lo siento, no puedo and a reason with tengo que.","You say you are available with estoy libre."]},{"id":"es-a2-u06-rev1","unit_id":"es-a2-u06","position":3,"title_es":"Review 1","objective_es":"Consolidate “¿Quieres venir?” and “Lo siento, no puedo”.","intro":null,"takeaways":[]},{"id":"es-a2-u06-l03","unit_id":"es-a2-u06","position":4,"title_es":"Nos vemos el sábado","objective_es":"Arrange when and where to meet.","intro":{"explanation":"To suggest a place and a time: nos encontramos en… (let’s meet at…, literally we meet): nos encontramos en la estación a las ocho. Próximo (next) goes before the noun and agrees with it: el próximo sábado, la próxima semana. En dos días means in two days from now. To say goodbye until then: nos vemos (see you), nos vemos el sábado.","examples":[{"target":"Nos encontramos en la estación a las ocho.","base":"Let’s meet at the station at eight."},{"target":"Nos vemos el próximo sábado.","base":"See you next Saturday."}]},"takeaways":["You suggest a meeting point with nos encontramos en…","You say when with el próximo…, en dos días and close with nos vemos."]},{"id":"es-a2-u06-l04","unit_id":"es-a2-u06","position":5,"title_es":"Iré, haré, será","objective_es":"Recognize and use the simple future in plans, promises and announcements.","intro":{"explanation":"In everyday conversation, Latin Americans usually talk about plans with ir a + infinitive: voy a ir, voy a hacer una fiesta. The simple future appears more in writing, in promises and in predictions. Regular verbs add -é for yo, -ás for tú and -á for él / ella to the infinitive (ser → serás, será). Some shorten the stem: hacer → haré, venir → vendré, haber → habrá (there will be, the future of hay). The stress is always on the last syllable, which carries the accent: iré, será. Don’t mix up habrá (there will be) and había (there was).","examples":[{"target":"El sábado habrá música en la plaza.","base":"There will be music in the square on Saturday."},{"target":"Mañana iré al banco.","base":"Tomorrow I’ll go to the bank."}]},"takeaways":["You recognize the simple future: iré, haré, vendré, será, habrá.","You use voy a + infinitive for everyday plans and the simple future for promises and announcements."]},{"id":"es-a2-u06-rev2","unit_id":"es-a2-u06","position":6,"title_es":"Review 2","objective_es":"Consolidate “Nos vemos el sábado” and “Iré, haré, será”.","intro":null,"takeaways":[]},{"id":"es-a2-u06-l05","unit_id":"es-a2-u06","position":7,"title_es":"¿Qué plan tienes?","objective_es":"Understand a reply to an invitation and suggest another plan.","intro":{"explanation":"A polite written refusal thanks first, then apologizes and suggests something else: ¡Gracias por invitarme! Lo siento, pero… ¿Estás libre el próximo viernes? Messages between friends in much of Latin America end with un beso (the written version of the kiss on the cheek) or un abrazo (a hug). Listen to the music of the sentence: an invitation rises at the end (¿quieres venir?), while a polite refusal falls gently, starting with lo siento.","examples":[{"target":"¡Gracias por invitarme! Lo siento, pero no puedo.","base":"Thanks for inviting me! I’m sorry, but I can’t."},{"target":"¿Estás libre el próximo viernes?","base":"Are you free next Friday?"}]},"takeaways":["You understand a polite refusal with a new proposal.","You thank, apologize and suggest another plan."]},{"id":"es-a2-u06-listen","unit_id":"es-a2-u06","position":8,"title_es":"Listening practice","objective_es":"Recognize the words and phrases of the unit by ear.","intro":null,"takeaways":[]},{"id":"es-a2-u06-words","unit_id":"es-a2-u06","position":9,"title_es":"Words of the unit","objective_es":"Fix the vocabulary of the unit: recognize it and write it.","intro":null,"takeaways":[]},{"id":"es-a2-u06-final","unit_id":"es-a2-u06","position":10,"title_es":"Final review","objective_es":"Show everything from “Invitations and plans”.","intro":null,"takeaways":[]},{"id":"es-a2-u07-l01","unit_id":"es-a2-u07","position":1,"title_es":"Tengo que…","objective_es":"Say what you have to do and what one has to do at work.","intro":{"explanation":"Tener que + infinitive means to have to: tengo que, tienes que (tú), tiene que (usted, él, ella), tenemos que, tienen que (ustedes, ellos). Notice the change in tienes and tiene: the e becomes ie, but yo tengo has a g. The que is never dropped: tengo que trabajar. Hay que + infinitive has no subject: it is a general rule, like “you have to” or “one has to” in English. Reunión ends in -ión, so the stress falls on the last syllable and it carries an accent.","examples":[{"target":"Hoy tengo que trabajar hasta tarde.","base":"Today I have to work late."},{"target":"En la oficina hay que llegar a tiempo.","base":"At the office you have to be on time."}]},"takeaways":["You say what you have to do with tengo que + infinitive.","You state a general rule with hay que + infinitive."]},{"id":"es-a2-u07-l02","unit_id":"es-a2-u07","position":2,"title_es":"¿Puedo…?","objective_es":"Say what you can and can’t do, and talk about exams.","intro":{"explanation":"Poder + infinitive means can: puedo, puedes (tú), puede (usted, él, ella), podemos, pueden (ustedes, ellos). The o becomes ue in puedo, puedes, puede and pueden, but not in podemos. No puedo is I can’t. Aprobar un examen means to pass an exam (it does not mean to approve). In several Latin American countries, such as Mexico and Argentina, public universities are free or almost free.","examples":[{"target":"¿Puedes venir mañana? — No, no puedo.","base":"Can you come tomorrow? — No, I can’t."},{"target":"Tengo que aprobar el examen.","base":"I have to pass the exam."}]},"takeaways":["You say what you can or can’t do with puedo and no puedo.","You talk about exams and university with el examen, aprobar and la universidad."]},{"id":"es-a2-u07-rev1","unit_id":"es-a2-u07","position":3,"title_es":"Review 1","objective_es":"Consolidate “Tengo que…” and “¿Puedo…?”.","intro":null,"takeaways":[]},{"id":"es-a2-u07-l03","unit_id":"es-a2-u07","position":4,"title_es":"Desde hace tres años","objective_es":"Say how long and since when you have been working or studying.","intro":{"explanation":"To say how long something has been going on, Spanish uses the present tense, not a past form: trabajo acá desde hace tres años means I have been working here for three years. Use desde hace with a period of time (dos meses, un año) and desde alone with a starting point (desde marzo). Durante means during: durante la semana. To ask: ¿desde cuándo…?","examples":[{"target":"Estudio inglés desde hace dos años.","base":"I’ve been studying English for two years."},{"target":"Vivo en Bogotá desde enero.","base":"I’ve lived in Bogotá since January."}]},"takeaways":["You say how long with the present tense + desde hace.","You use desde with a starting point and durante for during."]},{"id":"es-a2-u07-l04","unit_id":"es-a2-u07","position":5,"title_es":"La entrevista","objective_es":"Understand and answer questions in a job interview.","intro":{"explanation":"In a job interview people usually speak with usted: ¿me trae su currículum?, ¿puede trabajar los sábados? With your coworkers you usually switch to tú. A pasantía is an internship for students, often paid (in Mexico people also say las prácticas). Pronunciation: c before a, o or u sounds like k (currículum, compañero), and before e or i like s (oficina, cine). The rr of currículum is trilled.","examples":[{"target":"Mañana tengo una entrevista de trabajo.","base":"Tomorrow I have a job interview."},{"target":"¿Me trae su currículum, por favor?","base":"Could you bring me your CV, please?"}]},"takeaways":["You understand the typical questions of a job interview with usted.","You talk about the CV, the salary, a job and an internship."]},{"id":"es-a2-u07-rev2","unit_id":"es-a2-u07","position":6,"title_es":"Review 2","objective_es":"Consolidate “Desde hace tres años” and “La entrevista”.","intro":null,"takeaways":[]},{"id":"es-a2-u07-l05","unit_id":"es-a2-u07","position":7,"title_es":"Un aviso y un mensaje","objective_es":"Understand a job ad and a message about work and studies.","intro":{"explanation":"A job ad tells you what you have to do (hay que…) and what the job offers. Si means if: si apruebo means if I pass. Words in -ión like reunión lose the accent mark in the plural (reuniones) but keep the stress in the same place.","examples":[{"target":"Hay que mandar el currículum antes del viernes.","base":"You have to send your CV before Friday."},{"target":"Si apruebo el examen, tengo el título.","base":"If I pass the exam, I get my degree."}]},"takeaways":["You understand the requirements in a job ad.","You talk about meetings, exams and your degree."]},{"id":"es-a2-u07-listen","unit_id":"es-a2-u07","position":8,"title_es":"Listening practice","objective_es":"Recognize the words and phrases of the unit by ear.","intro":null,"takeaways":[]},{"id":"es-a2-u07-words","unit_id":"es-a2-u07","position":9,"title_es":"Words of the unit","objective_es":"Fix the vocabulary of the unit: recognize it and write it.","intro":null,"takeaways":[]},{"id":"es-a2-u07-final","unit_id":"es-a2-u07","position":10,"title_es":"Final review","objective_es":"Show everything from “Work and studies”.","intro":null,"takeaways":[]},{"id":"es-a2-u08-l01","unit_id":"es-a2-u08","position":1,"title_es":"Me duele la cabeza","objective_es":"Say what hurts with me duele and me duelen.","intro":{"explanation":"To say something hurts, Spanish turns the sentence around, like gustar: me duele la cabeza is literally “the head hurts me”. Use duele with one thing and duelen with more than one: me duelen los dientes. With parts of the body Spanish uses the article, not my: me duele la cabeza, not mi cabeza. To ask a friend: ¿te duele…?","examples":[{"target":"Me duele la cabeza.","base":"I have a headache."},{"target":"¿Te duelen los dientes?","base":"Do your teeth hurt?"}]},"takeaways":["You say what hurts with me duele + one thing and me duelen + several.","You use la, el or los with parts of the body, not mi."]},{"id":"es-a2-u08-l02","unit_id":"es-a2-u08","position":2,"title_es":"¿Cómo te sientes?","objective_es":"Say how you feel and that you are sick.","intro":{"explanation":"Me siento + bien, mal or cansado means I feel… Sentirse changes e to ie: me siento, te sientes, se siente. To ask a friend: ¿cómo te sientes? (to usted: ¿cómo se siente?). Estoy enfermo or estoy enferma (I’m sick) uses estar, because it is a state, not who you are. In garganta, the g before a, o or u is hard, like the g in go.","examples":[{"target":"¿Cómo te sientes? — Me siento mal.","base":"How do you feel? — I feel bad."},{"target":"Estoy enferma: me duele la garganta.","base":"I’m sick: my throat hurts."}]},"takeaways":["You say how you feel with me siento bien or me siento mal.","You say you are sick with estoy enfermo or estoy enferma."]},{"id":"es-a2-u08-rev1","unit_id":"es-a2-u08","position":3,"title_es":"Review 1","objective_es":"Consolidate “Me duele la cabeza” and “¿Cómo te sientes?”.","intro":null,"takeaways":[]},{"id":"es-a2-u08-l03","unit_id":"es-a2-u08","position":4,"title_es":"En el médico","objective_es":"Understand a doctor’s questions and instructions.","intro":{"explanation":"At the doctor’s, people speak with usted: ¿qué le pasa?, ¿le duele…? The doctor gives instructions with the usted imperative: tome este remedio, descanse. A cold is el resfriado (in Argentina and Chile you will also hear el resfrío). For medicine you will hear both el remedio and la medicina. La receta is the prescription (the same word means recipe). Tener fiebre, to have a fever, has no article.","examples":[{"target":"Tengo fiebre desde ayer.","base":"I’ve had a fever since yesterday."},{"target":"Tome el remedio tres veces al día.","base":"Take the medicine three times a day."}]},"takeaways":["You understand ¿qué le pasa? and instructions like tome and descanse.","You talk about a fever, a cold, medicine and a prescription."]},{"id":"es-a2-u08-l04","unit_id":"es-a2-u08","position":5,"title_es":"Descansa, no tomes café","objective_es":"Give a friend health advice with the imperative.","intro":{"explanation":"To give a friend (tú) advice, use the same form as él or ella in the present: descansa (rest!), toma (take! or drink!), bebe (drink!). In Latin America tomar is the everyday verb for drinking. For negative advice the vowel swaps: -ar verbs take -es and -er / -ir verbs take -as: no tomes, no descanses, no comas. With usted the vowel also swaps: tome, descanse, no tome. Listen to the last vowel: toma (take!, to a friend), tomo (I take) and tome (take!, to usted) are three different words.","examples":[{"target":"Descansa y toma mucha agua.","base":"Rest and drink lots of water."},{"target":"No tomes café por la noche.","base":"Don’t drink coffee at night."}]},"takeaways":["You give advice to a friend with descansa or toma, the same form as él / ella.","You say what not to do with no tomes, no comas: the vowel swaps."]},{"id":"es-a2-u08-rev2","unit_id":"es-a2-u08","position":6,"title_es":"Review 2","objective_es":"Consolidate “En el médico” and “Descansa, no tomes café”.","intro":null,"takeaways":[]},{"id":"es-a2-u08-l05","unit_id":"es-a2-u08","position":7,"title_es":"¡Que te mejores!","objective_es":"Understand a message to a sick friend and wish someone well.","intro":{"explanation":"When a friend is sick, say ¡que te mejores! (get well soon!); with usted it is ¡que se mejore! It uses a verb form you will learn later, the subjunctive (the same one as in no tomes): for now, learn it as a fixed expression. And all over the Spanish-speaking world, when someone sneezes, people say ¡salud!","examples":[{"target":"¿Estás enfermo? ¡Que te mejores!","base":"Are you sick? Get well soon!"},{"target":"Descansa mucho. ¡Que te mejores!","base":"Get lots of rest. Get well soon!"}]},"takeaways":["You wish a friend well with ¡que te mejores!","You understand advice in a message to someone who is sick."]},{"id":"es-a2-u08-listen","unit_id":"es-a2-u08","position":8,"title_es":"Listening practice","objective_es":"Recognize the words and phrases of the unit by ear.","intro":null,"takeaways":[]},{"id":"es-a2-u08-words","unit_id":"es-a2-u08","position":9,"title_es":"Words of the unit","objective_es":"Fix the vocabulary of the unit: recognize it and write it.","intro":null,"takeaways":[]},{"id":"es-a2-u08-final","unit_id":"es-a2-u08","position":10,"title_es":"Final review","objective_es":"Show everything from “Health”.","intro":null,"takeaways":[]},{"id":"es-a2-u09-l01","unit_id":"es-a2-u09","position":1,"title_es":"Mejor, peor, más caro","objective_es":"Compare clothes and prices.","intro":{"explanation":"To compare, use más + adjective + que (more … than), menos + adjective + que (less … than) or tan + adjective + como (as … as). The adjective agrees with the noun: la camisa es más cara. Bueno and malo have their own forms: mejor (better) and peor (worse). Watch out for a false friend: largo means long, not large. El pantalón is singular in Spanish, but in English you say trousers.","examples":[{"target":"La camisa es más cara que el pantalón.","base":"The shirt is more expensive than the trousers."},{"target":"Este vestido es mejor que el rojo.","base":"This dress is better than the red one."}]},"takeaways":["You compare with más… que, menos… que and tan… como.","You say better and worse with mejor and peor."]},{"id":"es-a2-u09-l02","unit_id":"es-a2-u09","position":2,"title_es":"El más barato, carísimo","objective_es":"Say what is the cheapest, the best or really expensive.","intro":{"explanation":"To say the most: el, la, los or las + noun + más + adjective + de: la chaqueta más barata del negocio (the cheapest jacket in the shop; Spanish uses de, not en). To say really, add -ísimo: caro → carísimo, barato → baratísimo. The stress always falls on the í of -ísimo, and it always has an accent mark. A jacket is una chaqueta, and in much of Latin America sneakers are los tenis (the same word as the sport, and it never changes: un tenis, dos tenis). In Argentina, Peru and Spain you will also hear las zapatillas.","examples":[{"target":"Son los tenis más baratos del negocio.","base":"They’re the cheapest sneakers in the shop."},{"target":"¡Esta chaqueta es carísima!","base":"This jacket is really expensive!"}]},"takeaways":["You say the most with el más or la más + adjective + de.","You say really expensive with carísimo, stressed on the í."]},{"id":"es-a2-u09-rev1","unit_id":"es-a2-u09","position":3,"title_es":"Review 1","objective_es":"Consolidate “Mejor, peor, más caro” and “El más barato, carísimo”.","intro":null,"takeaways":[]},{"id":"es-a2-u09-l03","unit_id":"es-a2-u09","position":4,"title_es":"¿Me lo puedo probar?","objective_es":"Ask for your size and try clothes on.","intro":{"explanation":"Clothes come in tallas (sizes) and shoes in números. The ll of talla sounds like the y in yes. Probarse means to try on. To avoid repeating the noun, use lo for a masculine thing (el pantalón → lo) and la for a feminine one (la camisa → la); los and las for plurals. The pronoun goes before the conjugated verb: ¿me lo puedo probar? (can I try it on?). Try clothes on in el probador.","examples":[{"target":"Me gusta este pantalón. ¿Me lo puedo probar?","base":"I like these trousers. Can I try them on?"},{"target":"¿Tiene estos tenis en el número cuarenta?","base":"Do you have these sneakers in size forty?"}]},"takeaways":["You ask for your size with talla (clothes) and número (shoes).","You ask to try something on with ¿me lo puedo probar? or ¿me la puedo probar?"]},{"id":"es-a2-u09-l04","unit_id":"es-a2-u09","position":5,"title_es":"Me lo llevo","objective_es":"Say you’ll buy something and choose how to pay.","intro":{"explanation":"To say you’ll buy something: me lo llevo (I’ll take it), me la llevo for a feminine thing, me los llevo or me las llevo for plurals. If something fits or suits you: me queda bien. You pay con tarjeta (by card) or en efectivo (in cash). A liquidación is a sale: many shops have big sales at the end of each season (you will also hear las rebajas and las ofertas).","examples":[{"target":"Me gusta. Me lo llevo.","base":"I like it. I’ll take it."},{"target":"¿Puedo pagar con tarjeta?","base":"Can I pay by card?"}]},"takeaways":["You say you’ll buy something with me lo llevo or me la llevo.","You pay con tarjeta or en efectivo."]},{"id":"es-a2-u09-rev2","unit_id":"es-a2-u09","position":6,"title_es":"Review 2","objective_es":"Consolidate “¿Me lo puedo probar?” and “Me lo llevo”.","intro":null,"takeaways":[]},{"id":"es-a2-u09-l05","unit_id":"es-a2-u09","position":7,"title_es":"¡Liquidación!","objective_es":"Understand a sale ad and talk about the best prices.","intro":{"explanation":"Sale ads use comparisons and superlatives: los tenis más baratos de la ciudad. El mejor and la mejor + noun mean the best: la mejor chaqueta del negocio. Some shops give a discount if you pay en efectivo.","examples":[{"target":"Los tenis más baratos de la ciudad.","base":"The cheapest sneakers in town."},{"target":"Es la mejor chaqueta del negocio.","base":"It’s the best jacket in the shop."}]},"takeaways":["You understand the offers in a sale ad.","You say the best with el mejor or la mejor + noun."]},{"id":"es-a2-u09-listen","unit_id":"es-a2-u09","position":8,"title_es":"Listening practice","objective_es":"Recognize the words and phrases of the unit by ear.","intro":null,"takeaways":[]},{"id":"es-a2-u09-words","unit_id":"es-a2-u09","position":9,"title_es":"Words of the unit","objective_es":"Fix the vocabulary of the unit: recognize it and write it.","intro":null,"takeaways":[]},{"id":"es-a2-u09-final","unit_id":"es-a2-u09","position":10,"title_es":"Final review","objective_es":"Show everything from “Shopping and services”.","intro":null,"takeaways":[]},{"id":"es-a2-u10-l01","unit_id":"es-a2-u10","position":1,"title_es":"La compu y el celular","objective_es":"Name the parts of your digital life: computer, screen, app, password, messages.","intro":{"explanation":"In Latin America a computer is la computadora (informally la compu; in Spain, el ordenador) and a mobile phone is el celular (in Spain, el móvil). An email is el mail, borrowed from English, or el correo, and an app is la app. Watch the gender: la pantalla and la contraseña are feminine, el mensaje is masculine even though it ends in -e. The ñ of contraseña sounds like the ny in canyon. Conectado means online; for a woman, conectada.","examples":[{"target":"La pantalla de la computadora es grande.","base":"The computer screen is big."},{"target":"¿Estás conectado? — Sí, estoy en la compu.","base":"Are you online? — Yes, I’m on the computer."}]},"takeaways":["You name the computer, the screen, the app, the password, messages and emails.","You say someone is online with conectado or conectada."]},{"id":"es-a2-u10-l02","unit_id":"es-a2-u10","position":2,"title_es":"Mandar, recibir, bajar","objective_es":"Say what you send, receive, download and call, and say a device isn’t working.","intro":{"explanation":"Mandar (to send), llamar (to call) and bajar (to download) are regular -ar verbs: in the past, mandé, llamé, bajé (yo) and mandaste, llamaste, bajaste (tú). Recibir (to receive) is an -ir verb: recibí, recibiste. Bajar literally means to go down; in everyday speech it also means to download (the standard word is descargar). With a person, llamar needs a: llamo a mi abuela. For devices, use funcionar: el celular no funciona (the phone isn’t working). In Argentina and some other countries people also say no anda.","examples":[{"target":"Ayer bajé la app del banco.","base":"Yesterday I downloaded the bank app."},{"target":"El celular no funciona.","base":"The phone isn’t working."}]},"takeaways":["You use mandar, recibir, llamar and bajar in the present and the past.","You say a device isn’t working with no funciona."]},{"id":"es-a2-u10-rev1","unit_id":"es-a2-u10","position":3,"title_es":"Review 1","objective_es":"Consolidate “La compu y el celular” and “Mandar, recibir, bajar”.","intro":null,"takeaways":[]},{"id":"es-a2-u10-l03","unit_id":"es-a2-u10","position":4,"title_es":"Lo llamo, la veo","objective_es":"Replace a person or a thing with lo, la, los, las.","intro":{"explanation":"Lo, la, los and las replace the person or thing that receives the action: lo for a man or a masculine noun, la for a woman or a feminine noun, los and las for plurals. Unlike English, they go before the conjugated verb: lo llamo (I call him), la veo (I see her). With no, the order is no + pronoun + verb: no lo tengo. The ll of llamo sounds like the y in yes.","examples":[{"target":"¿Y Martín? — Lo llamo ahora.","base":"What about Martín? — I’ll call him now."},{"target":"¿La app? La bajé ayer.","base":"The app? I downloaded it yesterday."}]},"takeaways":["You put lo, la, los and las before the conjugated verb.","You choose the pronoun by gender and number: lo, la, los, las."]},{"id":"es-a2-u10-l04","unit_id":"es-a2-u10","position":5,"title_es":"Le escribo, se lo mando","objective_es":"Say who you write, talk or send things to, with le, les and se lo.","intro":{"explanation":"Le and les mark the person who gets something: le escribo (I write to him or to her), les hablo (I talk to them). Spanish usually keeps the person as well: le escribo a Diego, les hablo a los estudiantes. When le or les meets lo, la, los or las, it changes to se: se lo mando (I send it to him), never “le lo”. The order is always person first, then thing: se lo, te la, me lo.","examples":[{"target":"Le escribo un mail a la profesora.","base":"I’m writing an email to the teacher."},{"target":"¿El mail para Juan? Se lo mando hoy.","base":"The email for Juan? I’ll send it to him today."}]},"takeaways":["You use le and les for the person who receives something.","You turn le lo into se lo: se lo mando."]},{"id":"es-a2-u10-rev2","unit_id":"es-a2-u10","position":6,"title_es":"Review 2","objective_es":"Consolidate “Lo llamo, la veo” and “Le escribo, se lo mando”.","intro":null,"takeaways":[]},{"id":"es-a2-u10-l05","unit_id":"es-a2-u10","position":7,"title_es":"Voy a llamarlo","objective_es":"Understand messages about technology and use pronouns with infinitives.","intro":{"explanation":"With an infinitive (llamar, leer, bajar) the pronoun has two possible places: before the conjugated verb or attached to the end of the infinitive, as one word. Lo voy a llamar = voy a llamarlo; tienes que leerlo. Never use both at once. With an affirmative tú command it is also attached: llámame (call me). The stress stays where it was: lla-MAR-lo, LLA-ma-me. That is why llámame needs a written accent: the stress is now three syllables from the end.","examples":[{"target":"Voy a llamarlo esta noche.","base":"I’m going to call him tonight."},{"target":"Lo voy a llamar esta noche.","base":"I’m going to call him tonight."}]},"takeaways":["You put the pronoun before voy a or at the end of the infinitive: lo voy a llamar = voy a llamarlo.","You understand a message or a call about a device that isn’t working."]},{"id":"es-a2-u10-listen","unit_id":"es-a2-u10","position":8,"title_es":"Listening practice","objective_es":"Recognize the words and phrases of the unit by ear.","intro":null,"takeaways":[]},{"id":"es-a2-u10-words","unit_id":"es-a2-u10","position":9,"title_es":"Words of the unit","objective_es":"Fix the vocabulary of the unit: recognize it and write it.","intro":null,"takeaways":[]},{"id":"es-a2-u10-final","unit_id":"es-a2-u10","position":10,"title_es":"Final review","objective_es":"Show everything from “Technology”.","intro":null,"takeaways":[]},{"id":"es-a2-u11-l01","unit_id":"es-a2-u11","position":1,"title_es":"Me desperté, nos conocimos","objective_es":"Say when you woke up and tell how you met someone.","intro":{"explanation":"Reflexive verbs carry a pronoun that matches the subject: me desperté (I woke up), te despertaste (you woke up, tú), se despertó (he or she woke up; also usted). With nos, the action is often mutual: nos conocimos (we met, literally “we got to know each other”). In the past, conocer is the verb for meeting someone for the first time. El novio and la novia are boyfriend and girlfriend; la pareja (partner, or couple) is always feminine, even when it is a man.","examples":[{"target":"Hoy me desperté muy tarde.","base":"Today I woke up very late."},{"target":"Mi novio y yo nos conocimos en un viaje.","base":"My boyfriend and I met on a trip."}]},"takeaways":["You use me desperté and nos conocimos to tell a story in the past.","You talk about your novio, novia or pareja."]},{"id":"es-a2-u11-l02","unit_id":"es-a2-u11","position":2,"title_es":"Casarse, pelearse, llevarse bien","objective_es":"Say who got married, who argues and who gets along.","intro":{"explanation":"Some verbs come with -se in the infinitive: casarse (to get married), pelearse (to argue), llevarse bien (to get along). The se changes with the person: nos casamos, se casaron (they got married), se pelean, me llevo bien con mi hermana. Note the preposition: llevarse bien con alguien, casarse con alguien. Juntos (together) agrees like an adjective: juntas for women. The wedding itself is la boda (in Argentina, el casamiento).","examples":[{"target":"Mis padres se casaron en el verano.","base":"My parents got married in the summer."},{"target":"Me llevo muy bien con mi hermana.","base":"I get along very well with my sister."}]},"takeaways":["You use casarse, pelearse and llevarse bien with the right pronoun.","You say together with juntos or juntas."]},{"id":"es-a2-u11-rev1","unit_id":"es-a2-u11","position":3,"title_es":"Review 1","objective_es":"Consolidate “Me desperté, nos conocimos” and “Casarse, pelearse, llevarse bien”.","intro":null,"takeaways":[]},{"id":"es-a2-u11-l03","unit_id":"es-a2-u11","position":4,"title_es":"Nunca, nada, nadie","objective_es":"Say what never, no longer or hardly ever happens, with double negatives.","intro":{"explanation":"In Spanish two negatives don’t cancel each other: no + verb + nada, nadie or nunca. No tengo nada (I don’t have anything), no vino nadie (nobody came). If nunca or nadie goes before the verb, you drop no: nunca tomo café. The opposites are algo (something) / nada, alguien (someone) / nadie, siempre / nunca. Ya no means no longer, and casi nunca means hardly ever.","examples":[{"target":"No vino nadie a la fiesta.","base":"Nobody came to the party."},{"target":"Ya no vivo en Guadalajara.","base":"I no longer live in Guadalajara."}]},"takeaways":["You make double negatives: no tengo nada, no vino nadie.","You use nunca, casi nunca and ya no to talk about frequency and change."]},{"id":"es-a2-u11-l04","unit_id":"es-a2-u11","position":5,"title_es":"¿Alguna vez…?","objective_es":"Ask and answer about life experiences, and recognise the present perfect.","intro":{"explanation":"The present perfect is he (yo), has (tú), ha (él, ella, usted) + a participle ending in -ado or -ido: he estado (I have been), ha sido (it has been). In Spain it is used all the time for the recent past. In Latin America the simple past is the everyday past, even for experiences: ¿Alguna vez fuiste a Cancún? (Have you ever been to Cancún?). The perfect is still used in some contexts, especially for life experiences (¿alguna vez has estado en Cancún?) and for a period that is not over (ha sido un día largo), so you will hear and read both. Alguna vez means ever. The h is silent: he, has and ha sound exactly like e, as and a.","examples":[{"target":"¿Alguna vez fuiste a Cancún? — No, nunca.","base":"Have you ever been to Cancún? — No, never."},{"target":"Nunca he estado en Cusco.","base":"I have never been to Cusco."}]},"takeaways":["You ask about experiences with ¿alguna vez…?","You recognise he estado and ha sido and know that the h is silent."]},{"id":"es-a2-u11-rev2","unit_id":"es-a2-u11","position":6,"title_es":"Review 2","objective_es":"Consolidate “Nunca, nada, nadie” and “¿Alguna vez…?”.","intro":null,"takeaways":[]},{"id":"es-a2-u11-l05","unit_id":"es-a2-u11","position":7,"title_es":"Historias de pareja","objective_es":"Understand and tell a short story about a relationship.","intro":{"explanation":"To tell a love story, people in Latin America use the simple past for the events (nos conocimos, se casaron) and the present for how things are now (se llevan bien, ya no están juntos). Hace + time means ago: nos conocimos hace dos años. Nosotros forms of -ar verbs are the same in the present and the past (nos peleamos = we argue / we argued): the context tells you which.","examples":[{"target":"Nos conocimos hace dos años y ahora vivimos juntos.","base":"We met two years ago and now we live together."},{"target":"Nunca nos peleamos.","base":"We never argue."}]},"takeaways":["You tell how a couple met, when they got married and how they get along.","You understand a post about a first experience."]},{"id":"es-a2-u11-listen","unit_id":"es-a2-u11","position":8,"title_es":"Listening practice","objective_es":"Recognize the words and phrases of the unit by ear.","intro":null,"takeaways":[]},{"id":"es-a2-u11-words","unit_id":"es-a2-u11","position":9,"title_es":"Words of the unit","objective_es":"Fix the vocabulary of the unit: recognize it and write it.","intro":null,"takeaways":[]},{"id":"es-a2-u11-final","unit_id":"es-a2-u11","position":10,"title_es":"Final review","objective_es":"Show everything from “Relationships and experiences”.","intro":null,"takeaways":[]},{"id":"es-a2-u12-l01","unit_id":"es-a2-u12","position":1,"title_es":"Creo que, para mí","objective_es":"Give your opinion and say whether you agree.","intro":{"explanation":"To give your opinion, start with creo que (I think that), me parece que (it seems to me that) or para mí (in my opinion), followed by a normal sentence. Para mí has an accent on mí (me), which tells it apart from mi (my). To agree: estoy de acuerdo, literally “I am in agreement”, with estar (not a verb like in English), or tienes razón (you’re right; to usted: tiene razón). To disagree: no estoy de acuerdo. An opinion is said with a falling tone at the end, like a statement; to disagree politely, people slow down and soften it first: Mmm… para mí, no.","examples":[{"target":"Creo que el autobús es mejor que el metro.","base":"I think the bus is better than the subway."},{"target":"¿Estás de acuerdo? — Sí, tienes razón.","base":"Do you agree? — Yes, you’re right."}]},"takeaways":["You give your opinion with creo que, me parece que and para mí.","You agree with estoy de acuerdo or tienes razón, and disagree with no estoy de acuerdo."]},{"id":"es-a2-u12-l02","unit_id":"es-a2-u12","position":2,"title_es":"Deberías, podríamos","objective_es":"Give advice and suggest solutions to a problem.","intro":{"explanation":"For advice, use deberías + infinitive (you should); for a suggestion that includes you, podríamos + infinitive (we could). Both are in the conditional, which ends in -ía: debería (I should), deberías, podríamos. The accent on the í means the i is a separate, stressed syllable: de-be-RÍ-as, po-DRÍ-a-mos. Watch out: el problema is masculine even though it ends in -a, like el día. La solución is feminine.","examples":[{"target":"Deberías llamar a tu mamá.","base":"You should call your mom."},{"target":"Podríamos ir al cine.","base":"We could go to the cinema."}]},"takeaways":["You give advice with deberías and make suggestions with podríamos.","You talk about el problema and la solución."]},{"id":"es-a2-u12-rev1","unit_id":"es-a2-u12","position":3,"title_es":"Review 1","objective_es":"Consolidate “Creo que, para mí” and “Deberías, podríamos”.","intro":null,"takeaways":[]},{"id":"es-a2-u12-l03","unit_id":"es-a2-u12","position":4,"title_es":"Si llueve…","objective_es":"Talk about conditions, link ideas and say what you hope.","intro":{"explanation":"For a real condition, use si (if, without an accent; sí with an accent is yes) + present, and the present or ir a in the other half: si llueve, nos quedamos en casa. To link ideas: porque (because), por eso (that’s why) and sin embargo (however), which is a bit more formal than pero. Dice que + sentence reports what someone says. Ojalá (hopefully, I hope) comes from Arabic; it is followed by a special verb form, so learn it as a block: ¡ojalá que no llueva!","examples":[{"target":"Si llueve, nos quedamos en casa.","base":"If it rains, we’ll stay at home."},{"target":"¡Ojalá que no llueva!","base":"Hopefully it won’t rain!"}]},"takeaways":["You make conditions with si + present: si llueve, vamos al cine.","You link ideas with por eso and sin embargo, and hope with ojalá."]},{"id":"es-a2-u12-l04","unit_id":"es-a2-u12","position":5,"title_es":"Por y para · el dinero","objective_es":"Use por and para, talk about money and report what someone told you.","intro":{"explanation":"Para looks ahead: purpose (estudio para aprender), destination or the person something is for (es para ti, es para usted). Por looks back to a cause or shows the means: por la lluvia (because of the rain), por teléfono (by phone), por mensaje. Money is el dinero; in much of South America people also say la plata (literally silver). Devolver (to give back) changes o to ue: devuelvo, devuelves, devuelve (but devolvemos). Me dijo que reports what someone told you: me dijo que no tiene dinero.","examples":[{"target":"Estudio español para viajar.","base":"I study Spanish in order to travel."},{"target":"Me dijo que no tiene dinero.","base":"He told me that he has no money."}]},"takeaways":["You use para for purpose and recipients, and por for causes and means.","You report what someone said with dice que and me dijo que."]},{"id":"es-a2-u12-rev2","unit_id":"es-a2-u12","position":6,"title_es":"Review 2","objective_es":"Consolidate “Si llueve…” and “Por y para · el dinero”.","intro":null,"takeaways":[]},{"id":"es-a2-u12-l05","unit_id":"es-a2-u12","position":7,"title_es":"¿Qué hacemos?","objective_es":"Discuss a problem, disagree politely and agree on a solution.","intro":{"explanation":"When friends discuss a problem, they combine everything: an opinion (para mí…), advice (deberías…), a suggestion (podríamos…) and a condition (si llueve…). Questions rise at the end and statements fall. A polite disagreement usually starts softly and more slowly, with tienes razón, pero… or no sé, para mí… Oye (literally “hear!”) is an informal way to get a friend’s attention.","examples":[{"target":"Tienes razón, pero creo que es caro.","base":"You’re right, but I think it’s expensive."},{"target":"Me parece que podríamos llamarlo por teléfono.","base":"I think we could call him on the phone."}]},"takeaways":["You discuss a problem and propose a solution.","You disagree politely by softening your opinion."]},{"id":"es-a2-u12-listen","unit_id":"es-a2-u12","position":8,"title_es":"Listening practice","objective_es":"Recognize the words and phrases of the unit by ear.","intro":null,"takeaways":[]},{"id":"es-a2-u12-words","unit_id":"es-a2-u12","position":9,"title_es":"Words of the unit","objective_es":"Fix the vocabulary of the unit: recognize it and write it.","intro":null,"takeaways":[]},{"id":"es-a2-u12-final","unit_id":"es-a2-u12","position":10,"title_es":"Final review","objective_es":"Show everything from “Opinions and solutions”.","intro":null,"takeaways":[]}],"exercises":[{"id":"es-a1-u01-l01-e01","lesson_id":"es-a1-u01-l01","position":1,"type":"translation_choice","skill":"vocabulary","prompt_es":"What does “hola” mean?","payload":{"type":"translation_choice","word":"hola","options":["hello","goodbye","see you later","good evening"]},"answer":"hello","accepted_answers":[],"explanation_es":null,"difficulty":1,"recommended_seconds":12,"words":["es-hola"]},{"id":"es-a1-u01-l01-e02","lesson_id":"es-a1-u01-l01","position":2,"type":"translation_choice","skill":"vocabulary","prompt_es":"What does “adiós” mean?","payload":{"type":"translation_choice","word":"adiós","options":["goodbye","good morning","good afternoon","hello"]},"answer":"goodbye","accepted_answers":[],"explanation_es":null,"difficulty":1,"recommended_seconds":12,"words":["es-adios"]},{"id":"es-a1-u01-l01-e03","lesson_id":"es-a1-u01-l01","position":3,"type":"match_pairs","skill":"vocabulary","prompt_es":"Match each word with its meaning","payload":{"type":"match_pairs","pairs":[{"left":"buenos días","right":"good morning"},{"left":"buenas tardes","right":"good afternoon"},{"left":"buenas noches","right":"good evening"},{"left":"hasta luego","right":"see you later"}]},"answer":"","accepted_answers":[],"explanation_es":null,"difficulty":1,"recommended_seconds":30,"words":["es-buenos-dias","es-buenas-tardes","es-buenas-noches","es-hasta-luego"]},{"id":"es-a1-u01-l01-e04","lesson_id":"es-a1-u01-l01","position":4,"type":"listen_choice","skill":"listening","prompt_es":"Listen and choose what you hear","payload":{"type":"listen_choice","audioText":"Buenas tardes, señora.","options":["Buenas tardes, señora.","Buenas noches, señora.","Buenas tardes, señor.","Buenos días, señora."]},"answer":"Buenas tardes, señora.","accepted_answers":[],"explanation_es":null,"difficulty":1,"recommended_seconds":15,"words":["es-buenas-tardes","es-senora"]},{"id":"es-a1-u01-l01-e05","lesson_id":"es-a1-u01-l01","position":5,"type":"fill_blank","skill":"vocabulary","prompt_es":"Complete the sentence","payload":{"type":"fill_blank","sentence":"¡___, Martín!","translation":"Hi, Martín!","options":["Hola","Adiós","Señor","Señora"]},"answer":"Hola","accepted_answers":[],"explanation_es":"Hola is the everyday greeting, at any time of day. Adiós means goodbye. The h is never pronounced.","difficulty":1,"recommended_seconds":15,"words":["es-hola"]},{"id":"es-a1-u01-l01-e06","lesson_id":"es-a1-u01-l01","position":6,"type":"fill_blank","skill":"vocabulary","prompt_es":"Complete the sentence","payload":{"type":"fill_blank","sentence":"Buenos días, ___.","translation":"Good morning, sir.","options":["señor","señora","adiós","hola"]},"answer":"señor","accepted_answers":[],"explanation_es":"Señor is sir and señora is madam. The ñ sounds like the ny in canyon.","difficulty":1,"recommended_seconds":15,"words":["es-buenos-dias","es-senor"]},{"id":"es-a1-u01-l01-e07","lesson_id":"es-a1-u01-l01","position":7,"type":"translation_choice","skill":"vocabulary","prompt_es":"What does “hasta luego” mean?","payload":{"type":"translation_choice","word":"hasta luego","options":["see you later","good evening","hello","good afternoon"]},"answer":"see you later","accepted_answers":[],"explanation_es":null,"difficulty":1,"recommended_seconds":12,"words":["es-hasta-luego"]},{"id":"es-a1-u01-l01-e08","lesson_id":"es-a1-u01-l01","position":8,"type":"listen_choice","skill":"listening","prompt_es":"Listen and choose what you hear","payload":{"type":"listen_choice","audioText":"Adiós, señor. ¡Hasta luego!","options":["Adiós, señor. ¡Hasta luego!","Adiós, señora. ¡Hasta luego!","Hola, señor. ¡Buenos días!","Buenas noches, señor."]},"answer":"Adiós, señor. ¡Hasta luego!","accepted_answers":[],"explanation_es":null,"difficulty":1,"recommended_seconds":15,"words":["es-adios","es-hasta-luego"]},{"id":"es-a1-u01-l01-e09","lesson_id":"es-a1-u01-l01","position":9,"type":"translate_write","skill":"translation","prompt_es":"Translate into Spanish","payload":{"type":"translate_write","source":"Good morning, madam."},"answer":"Buenos días, señora.","accepted_answers":["Buen día, señora."],"explanation_es":null,"difficulty":1,"recommended_seconds":30,"words":["es-buenos-dias","es-senora"]},{"id":"es-a1-u01-l01-e10","lesson_id":"es-a1-u01-l01","position":10,"type":"translate_write","skill":"translation","prompt_es":"Translate into Spanish","payload":{"type":"translate_write","source":"Good evening, sir."},"answer":"Buenas noches, señor.","accepted_answers":[],"explanation_es":null,"difficulty":1,"recommended_seconds":30,"words":["es-buenas-noches","es-senor"]},{"id":"es-a1-u01-l02-e01","lesson_id":"es-a1-u01-l02","position":1,"type":"translation_choice","skill":"vocabulary","prompt_es":"What does “gracias” mean?","payload":{"type":"translation_choice","word":"gracias","options":["thank you","please","you're welcome","yes"]},"answer":"thank you","accepted_answers":[],"explanation_es":null,"difficulty":1,"recommended_seconds":12,"words":["es-gracias"]},{"id":"es-a1-u01-l02-e02","lesson_id":"es-a1-u01-l02","position":2,"type":"match_pairs","skill":"vocabulary","prompt_es":"Match each word with its meaning","payload":{"type":"match_pairs","pairs":[{"left":"gracias","right":"thank you"},{"left":"de nada","right":"you're welcome"},{"left":"por favor","right":"please"},{"left":"sí","right":"yes"}]},"answer":"","accepted_answers":[],"explanation_es":null,"difficulty":1,"recommended_seconds":30,"words":["es-gracias","es-de-nada","es-por-favor","es-si"]},{"id":"es-a1-u01-l02-e03","lesson_id":"es-a1-u01-l02","position":3,"type":"fill_blank","skill":"vocabulary","prompt_es":"Complete the sentence","payload":{"type":"fill_blank","sentence":"Gracias, señora. — De ___.","translation":"Thank you, madam. — You’re welcome.","options":["nada","favor","luego","día"]},"answer":"nada","accepted_answers":[],"explanation_es":"The answer to gracias is de nada.","difficulty":1,"recommended_seconds":15,"words":["es-de-nada"]},{"id":"es-a1-u01-l02-e04","lesson_id":"es-a1-u01-l02","position":4,"type":"listen_choice","skill":"listening","prompt_es":"Listen and choose what you hear","payload":{"type":"listen_choice","audioText":"Sí, gracias.","options":["Sí, gracias.","No, gracias.","Sí, por favor.","Hola, señora."]},"answer":"Sí, gracias.","accepted_answers":[],"explanation_es":null,"difficulty":1,"recommended_seconds":15,"words":["es-si","es-gracias"]},{"id":"es-a1-u01-l02-e05","lesson_id":"es-a1-u01-l02","position":5,"type":"translation_choice","skill":"vocabulary","prompt_es":"What does “por favor” mean?","payload":{"type":"translation_choice","word":"por favor","options":["please","thank you","no","goodbye"]},"answer":"please","accepted_answers":[],"explanation_es":null,"difficulty":1,"recommended_seconds":12,"words":["es-por-favor"]},{"id":"es-a1-u01-l02-e06","lesson_id":"es-a1-u01-l02","position":6,"type":"fill_blank","skill":"vocabulary","prompt_es":"Complete the sentence","payload":{"type":"fill_blank","sentence":"___, gracias.","translation":"No, thank you.","options":["No","Sí","Hola","Adiós"]},"answer":"No","accepted_answers":[],"explanation_es":"No is no. Sí, gracias would be yes, thank you.","difficulty":1,"recommended_seconds":15,"words":["es-no"]},{"id":"es-a1-u01-l02-e07","lesson_id":"es-a1-u01-l02","position":7,"type":"listen_choice","skill":"listening","prompt_es":"Listen and choose what you hear","payload":{"type":"listen_choice","audioText":"Por favor, señor.","options":["Por favor, señor.","Por favor, señora.","Gracias, señor.","De nada, señor."]},"answer":"Por favor, señor.","accepted_answers":[],"explanation_es":null,"difficulty":1,"recommended_seconds":15,"words":["es-por-favor","es-senor"]},{"id":"es-a1-u01-l02-e08","lesson_id":"es-a1-u01-l02","position":8,"type":"translation_choice","skill":"vocabulary","prompt_es":"What does “sí” mean?","payload":{"type":"translation_choice","word":"sí","options":["yes","no","please","hello"]},"answer":"yes","accepted_answers":[],"explanation_es":null,"difficulty":1,"recommended_seconds":12,"words":["es-si"]},{"id":"es-a1-u01-l02-e09","lesson_id":"es-a1-u01-l02","position":9,"type":"translate_write","skill":"translation","prompt_es":"Translate into Spanish","payload":{"type":"translate_write","source":"Yes, please."},"answer":"Sí, por favor.","accepted_answers":[],"explanation_es":null,"difficulty":1,"recommended_seconds":30,"words":["es-si","es-por-favor"]},{"id":"es-a1-u01-l02-e10","lesson_id":"es-a1-u01-l02","position":10,"type":"translate_write","skill":"translation","prompt_es":"Translate into Spanish","payload":{"type":"translate_write","source":"No, thank you, madam."},"answer":"No, gracias, señora.","accepted_answers":["No, gracias señora."],"explanation_es":null,"difficulty":1,"recommended_seconds":30,"words":["es-no","es-gracias","es-senora"]},{"id":"es-a1-u01-rev1-e01","lesson_id":"es-a1-u01-rev1","position":1,"type":"complete_word","skill":"vocabulary","prompt_es":"Write the whole word","payload":{"type":"complete_word","masked":"g_a_i_s","hint":"thank you"},"answer":"gracias","accepted_answers":[],"explanation_es":null,"difficulty":1,"recommended_seconds":20,"words":["es-gracias"]},{"id":"es-a1-u01-rev1-e02","lesson_id":"es-a1-u01-rev1","position":2,"type":"fill_blank","skill":"vocabulary","prompt_es":"Complete the sentence","payload":{"type":"fill_blank","sentence":"Buenos días, ___.","translation":"Good morning, sir.","options":["señor","señora","adiós","hola"]},"answer":"señor","accepted_answers":[],"explanation_es":"Señor is sir and señora is madam. The ñ sounds like the ny in canyon.","difficulty":1,"recommended_seconds":15,"word